INSERT INTO recipes (id, slug, title, description, cuisine, cook_time_minutes, servings, difficulty, image_url, tags, source_type, source_reference, verification_state, version) VALUES
('imp-810c132a4d2cd4e0', 'canh-chua-tom-dua-nam-bo', 'Canh chua tôm dứa Nam Bộ', 'Nước canh chua thanh từ dứa chín và cà chua, tôm tươi vừa chín tới, giá đỗ giòn, món canh cơm miền Nam ngày nóng.', 'vietnamese', 30, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Chua ngọt","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-59015074541ba061', 'canh-kho-qua-nhoi-tom', 'Canh khổ qua nhồi tôm', 'Khổ qua cắt khoanh nhồi nhân tôm-thịt băm dai ngọt, hầm nước dùng trong, món canh giải nhiệt quen thuộc ngày hè.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món canh","Giải nhiệt","Nam Bộ","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-9c678f92a5cb0812', 'canh-bi-dao-tom-tuoi', 'Canh bí đao tôm tươi', 'Bí đao xanh non nấu với tôm tươi ra nước canh trong veo ngọt thanh, món canh mát nhẹ dễ nấu cho bữa tối.', 'vietnamese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Thanh mát","Dễ nấu","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-80ce5736becc08da', 'canh-ca-chua-trung-nha-la', 'Canh cà chua trứng nhà lá', 'Trứng đánh tơi thành những vệt hoa vàng trong nước cà chua chua nhẹ, món canh nhanh mười phút cho bữa cơm vội.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nhanh","Dễ nấu","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-9473faeacd64d970', 'canh-nam-ga-xe-soi', 'Canh nấm gà xé sợi', 'Ức gà luộc xé sợi thả cùng nấm đùi gà ngọt nước, món canh trong không xương nhưng vẫn đậm đà cho bữa cơm.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Không xương","Dễ nấu","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-9ab5767266722397', 'canh-muc-ca-chua-chua-nhe', 'Canh mực cà chua chua nhẹ', 'Mực ống thái khoanh giòn ngọt nấu cùng cà chua chua nhẹ và gừng ấm, món canh biển đơn giản cho bữa tối.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Hải sản","Nhanh","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-61eac17e8f3042a9', 'canh-su-su-bam-thit', 'Canh su su băm thịt', 'Su su non nấu mềm ngọt cùng viên thịt băm tròn đều, món canh miềm mộc mạc nhớ mùa lạnh xứ núi.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Tây Nguyên","Dễ nấu","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-ad2b55ed85f0d109', 'canh-bap-cai-trung-cuon', 'Canh bắp cải trứng cuộn', 'Bắp cải thái sợi nấu ngọt nước cùng trứng đánh cuộn mỏng vàng, món canh thanh giản dị cho bữa cơm thường.', 'vietnamese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Bắc Bộ","Thanh đạm","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-7cfc6a2e9d8bf8a3', 'canh-rau-muong-tom-dong', 'Canh rau muống tôm đồng', 'Ngọn rau muống non nấu cùng tôm xay viên tròn mượt, món canh đồng quê giản dị mà ngọt nước cho bữa cơm mùa mưa.', 'vietnamese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Đồng quê","Nam Bộ","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-24cdd0b61f9ed162', 'canh-cua-dong-dau-phu', 'Canh cua đồng đậu phụ', 'Rêu cua lọc kỹ ra vị ngọt mát, đậu phụ trắng non và cà chua chua nhẹ, món canh đồng bằng Bắc Bộ trọn vị quê hương.', 'vietnamese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món canh","Bắc Bộ","Quê hương","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-15155ec6cc7b7713', 'ba-chi-nuong-sa-mat-ong', 'Ba chỉ nướng sả mật ong', 'Miếng ba chỉ dày ướp sả bầm và mật ong, nướng cháy cạnh thơm lừng, món mặn cuốn bánh tráng cuối tuần.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Nướng","Tiệc cuối tuần","Cuốn","Mặn"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-363ca9ee2c5f7738', 'bo-kho-banh-mi-dam-vi', 'Bò kho bánh mì đậm vị', 'Thịt bò hầm mềm tan trong nước kho sánh màu điều thơm sả, chan cùng ổ bánh mì nóng giòn, món sáng trứ danh Sài Gòn.', 'vietnamese', 120, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Bò kho","Bánh mì","Nam Bộ","Hầm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-3ec27a2b8f5e4345', 'ga-kho-gung-ot-hiem', 'Gà kho gừng ớt hiếm', 'Đùi gà kho gừng xay cay ấm, nước kho sánh keo bám màu vàng đẹp mắt, món mặn đưa cơm ngày mưa.', 'vietnamese', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kho","Đưa cơm","Gừng","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-323aae415415eb28', 'tom-kho-tieu-xanh', 'Tôm kho tiêu xanh', 'Tôm rim kiệt nước hàng đậm đà, tiêu xanh đập dập cay tê nhẹ, món mặn nhanh làm cho bữa tối bận rộn.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kho","Tiêu","Đưa cơm","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-3f1ad35e1f1ec87f', 'muc-rim-dua-mien-trung', 'Mực rim dứa miền Trung', 'Mực tươi rim cùng dứa chua ngọt và ớt cay nồng, món mặn đậm phong vị miền Trung nhớ nước mắm ruông.', 'vietnamese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Rim","Miền Trung","Hải sản","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-64e505d497388f4a', 'ca-hoi-ap-chao-toi-chanh', 'Cá hồi áp chảo tỏi chanh', 'Miếng cá hồi áp chảo da giòn rưới sốt tỏi-chanh chua thanh, món chiên nhanh hiện đại cho bữa tối bận rộn.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Áp chảo","Cá hồi","Nhanh","Hiện đại"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-6e4c264764981b8b', 'ga-xao-sa-ot-non', 'Gà xào sả ớt non', 'Sả bầm nhuyễn lên màu vàng thơm nồng, gà thấm đều cay nhẹ, món xào đặc trưng cho bữa cơm ngày thường.', 'vietnamese', 22, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Sả","Cay","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-53760c13ec1e452b', 'tom-xao-gia-do', 'Tôm xào giá đỗ', 'Giá đỗ giòn mọng xào nhanh hai phút cùng tôm vừa chín tới, món xào thanh nhẹ ra nước ngọt tự nhiên.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Hải sản","Nhanh","Thanh nhẹ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a47ef9289f5d0136', 'ca-rot-xao-trung', 'Cà rốt xào trứng', 'Cà rốt sợi vàng óng xào giòn cùng trứng bông mềm, món xào nhà đơn giản mà đủ chất cho bữa tối.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Rau củ","Nhanh","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-abdcd797955a6d6a', 'dau-phu-xao-ca-chua', 'Đậu phụ xào cà chua', 'Đậu phụ chiên sơ vàng cạnh rồi xào cùng cà chua nhừ ra sốt chua nhẹ, món mặn chay quen thuộc đưa cơm.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Chay","Đậu phụ","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-97f26ff4abe44f9b', 'nem-ran-nhan-cua-thit', 'Nem rán nhân cua thịt', 'Nem gói bánh tráng nhân cua-thịt băm đậm đà, chiên hai lần vỏ giòn rụm, món chiên không thể thiếu ngày lễ.', 'vietnamese', 50, 6, 'hard', '/frigo/illustrations/delicious-meal.png', '["Chiên","Nem","Ngày lễ","Bắc Bộ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-03cb4c492e643034', 'tom-chien-trung-mong', 'Tôm chiên trứng mỏng', 'Tôm lột vỏ chấm qua lớp trứng đánh bông chiên vàng, viền trứng phồng mỏng giòn, món chiên đơn giản trẻ em nào cũng mê.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Chiên","Tôm","Trẻ em","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-c4a65718d5cd4b3c', 'cha-gio-chay-nam-dau', 'Chả giò chay nấm đậu', 'Chả giò chay nhân nấm-đậu phụ-củ sợi giòn rụm, chấm nước tương gừng, món chay chiên không thua món mặn.', 'vietnamese', 50, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Chay","Chiên","Chả giò","Giòn"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f3c2431be267b74d', 'ca-hap-dua-gung', 'Cá hấp dứa gừng', 'Cá tươi hấp cùng miếng dứa chua ngọt và gừng ấm, nước hấp thanh mát, món hấp nhẹ vị miền Nam.', 'vietnamese', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Hấp","Cá","Dứa","Thanh mát"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-6118e8aa010584af', 'trung-hap-tom-chung', 'Trứng hấp tôm chưng', 'Trứng chưng tôm mặt láng như gương, hấp cách thủy mềm mượt, món ăn nhẹ dễ tiêu cho bữa tối.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hấp","Trứng","Nhẹ bụng","Dễ nấu"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-4ced29ad30507f2c', 'goi-cuon-tom-thit-rau-song', 'Gỏi cuốn tôm thịt rau sống', 'Gỏi cuốn Sài Gòn tôm-ba chỉ luộc cuốn mềm với giá-dưa leo, chấm tương đậu phộng béo ngậy, món cuốn mát lành.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cuốn","Sài Gòn","Mát lành","Khai vị"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-3a06ac78b572f3ae', 'nom-dua-leo-tom-chua-cay', 'Nộm dưa leo tôm chua cay', 'Dưa leo bào vỏ trộn tôm luộc giòn ngọt trong nước mắm chanh tỏi ớt, món nộm chua cay mở màn bữa tiệc.', 'vietnamese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nộm","Chua cay","Khai vị","Mát lành"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-21f32dccd464c605', 'pho-ga-pho-co', 'Phở gà phố cổ', 'Nước phở trong veo ngọt từ gà nguyên, bánh phở mềm chan thịt gà xé, món phở gà trứ danh phố cổ Hà Nội.', 'vietnamese', 80, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Phở","Hà Nội","Nước lèo","Bữa sáng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-ba737c5583985a50', 'bun-bo-hue-sa-ot', 'Bún bò Huế sả ớt', 'Nước lèo sả-dầu ớt đỏ gạch cay nồng, thịt bò chần tái mềm, tô bún bò Huế đậm chất cố đô khó quên.', 'vietnamese', 80, 4, 'hard', '/frigo/illustrations/delicious-meal.png', '["Bún bò","Huế","Cay","Bữa trưa"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-37a39eaa1edcd2e4', 'hu-tieu-tom-thit-nam-vang', 'Hủ tiếu tôm thịt Nam Vang', 'Tô hủ tiếu Nam Vang nước trong ngọt tôm-thịt, điểm trứng cút và giá giòn, món ăn sáng Nam Bộ đậm đà.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Hủ tiếu","Nam Bộ","Bữa sáng","Nước trong"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-0efa407066cdc8dd', 'bun-ca-tom-ca-chua', 'Bún cá tom cà chua', 'Miếng cá chiên sơ thấm sốt cà chua chua ngọt chan cùng bún tươi, tô bún cá ấm bụng ngày mưa.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Bún cá","Cà chua","Bữa trưa","Ấm bụng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b6aeb931b882e8a3', 'com-chay-dau-kho-nam', 'Cơm chay đậu kho nấm', 'Đậu phụ kho cùng nấm nước tương sánh thấm đậm, chan cơm trắng nóng, mâm cơm chay mười? bữa cơm chay thanh mặn đủ vị.', 'vietnamese', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Chay","Kho","Đậu phụ","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f0039d3d3f6299b3', 'nam-kho-dau-phu-tuong', 'Nấm kho đậu phụ tương', 'Nấm kho tương sánh đậm cùng đậu phụ thấm màu cánh gián, món mặn chay đậm đà cho ngày rằm.', 'vietnamese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Chay","Kho","Nấm","Ngày rằm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-e771ef1a49b2aeed', 'bong-cai-xao-nam-chay', 'Bông cải xào nấm chay', 'Bông cải xanh chần sơ xào cùng nấm nước tương, món chay mặn nhẹ giữ đủ xanh giòn cho mâm cơm chay.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Chay","Xào","Rau xanh","Dễ nấu"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-43e806b28c7b8bb5', 'com-chien-tom-trung', 'Cơm chiên tôm trứng', 'Hạt cơm nguội rang tơi rời quyện tôm-trứng-cà rốt, món cơm chiên nhà nhanh gọn cho bữa tối vội.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Nhanh","Cơm nguội","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f92a1c569c245541', 'mi-xao-bo-rau-cu', 'Mì xào bò rau củ', 'Sợi mì tươi áp chảo lửa lớn cùng bò mềm và cải-cà rốt giòn, món xào đậm xì dầu cho bữa tối nhanh gọn.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì xào","Nhanh","Đưa cơm","Xào lửa lớn"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f4665d594d941e4a', 'chao-ga-gung-nong', 'Cháo gà gừng nóng', 'Hạt gạo nấu nhừ tan trong nước gà ngọt, gừng sợi ấm bụng, tô cháo gà nóng cho buổi sáng se lạnh.', 'vietnamese', 50, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cháo","Bữa sáng","Ấm bụng","Dễ nấu"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-35164fb31de89c5f', 'goi-ga-bap-cai-chanh', 'Gỏi gà bắp cải chanh', 'Gà luộc xé sợi trộn bắp cải giòn trong nước chanh-ớt mặn ngọt, món gỏi khai vị nhẹ bụng.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi","Khai vị","Chua cay","Nhẹ bụng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-368d91563cb1879b', 'lau-thai-tom-ca-mien-tay', 'Lẩu Thái tôm cá miền Tây', 'Nước lẩu chua cay sả-chanh sôi li ti, nhúng tôm-cá tươi-nấm, nồi lẩu Thái miền Tây hâm nóng bữa tiệc nhà.', 'vietnamese', 50, 5, 'medium', '/frigo/illustrations/delicious-meal.png', '["Lẩu","Chua cay","Tiệc nhà","Nam Bộ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-c52c790faf9281da', 'lau-nam-chay-dau-phu', 'Lẩu nấm chay đậu phụ', 'Nước lẩu ngọt thanh từ nhiều loại nấm, nhúng cải-đậu phụ, nồi lẩu chay ấm bụng ngày rằm.', 'vietnamese', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Lẩu","Chay","Ngày rằm","Ấm bụng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-e9678cfa1bc90074', 'tom-xao-trung-ca-chua', 'Tôm xào trứng cà chua', 'Tôm giòn trứng mềm quyện sốt cà chua chua ngọt, món xào nhà Trung Hoa ba tầng vị cho bữa cơm nhanh.', 'chinese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Tôm","Trứng","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-387c41fb3a0c2297', 'ga-kung-pao-tu-xuyen', 'Gà Kung Pao Tứ Xuyên', 'Miếng gà xào ớt khô cay tê, đậu phộng rang giòn rụm, món Kung Pao Tứ Xuyên nổi tiếng chan cơm trắng.', 'chinese', 30, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Tứ Xuyên","Cay","Đậu phộng","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f5abd36e99d48d94', 'dau-phu-mapo-tu-xuyen', 'Đậu phụ Mapo Tứ Xuyên', 'Đậu phụ non om trong sốt mapo cay tê, hạt tiêu Tứ Xuyên tê đầu lưỡi, món trứ danh của vùng Tứ Xuyên.', 'chinese', 25, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Tứ Xuyên","Cay tê","Đậu phụ","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-242fd73cebd63651', 'suon-chua-ngot-quang-dong', 'Sườn chua ngọt Quảng Đông', 'Khúc sườn chiên vàng phủ sốt chua ngọt dứa bóng keo, món chiên-trộn Quảng Đông nổi tiếng tiệc tùng.', 'chinese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Chua ngọt","Quảng Đông","Sườn","Tiệc"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-34f3eb2438125614', 'bap-cai-xao-toi-quang-dong', 'Bắp cải xào tỏi Quảng Đông', 'Bắp cải xào lửa lớn giữ độ giòn ngọt, dầu tỏi thơm lừng, món xào rau nhanh chuẩn vị Quảng Đông.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Quảng Đông","Rau","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-2d508cd359edb61c', 'dau-phu-hap-tom-gung', 'Đậu phụ hấp tôm gừng', 'Đậu phụ non hấp cùng tôm tươi và gừng ấm như món dim sum nhà, chấm xì dầu hành lá thanh nhẹ.', 'chinese', 25, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Hấp","Dim sum","Đậu phụ","Tôm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-6eaf6ed6d417c52c', 'muc-chien-muoi-ot', 'Mực chiên muối ớt', 'Mực chiên giòn muối-ớt kiểu Hồng Kông, hành lá rang thơm cuối cùng, món nhậu khó cưỡng.', 'chinese', 25, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Chiên","Muối ớt","Hồng Kông","Món nhậu"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-d90dc5bbe2891a12', 'chao-thit-bam-gung', 'Cháo thịt bằm gừng', 'Cháo đặc kiểu Quảng Đông với thịt bằm viên gừng ấm và trứng luộc cắt múi, bữa sáng đầy đặn.', 'chinese', 45, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cháo","Quảng Đông","Bữa sáng","Ấm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b23ab24915e52866', 'com-chien-duong-chau', 'Cơm chiên Dương Châu', 'Cơm chiên Dương Châu đầy đặn tôm-thịt bằm-trứng-cà rốt hạt lự, hạt cơm tơi vàng chuẩn quán Quảng Đông.', 'chinese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Dương Châu","Quảng Đông","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-e83f58ebb9b02fbd', 'mi-dan-dan-tu-xuyen', 'Mì Đan Đan Tứ Xuyên', 'Mì Đan Đan trộn sốt cay tê vừng với thịt bằm xào giòn, vị Tứ Xuyên đánh thức cả vị giác.', 'chinese', 30, 2, 'medium', '/frigo/illustrations/delicious-meal.png', '["Đan Đan","Tứ Xuyên","Cay tê","Mì trộn"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-04d477399e49fe8e', 'mi-xao-bo-quang-dong', 'Mì xào bò Quảng Đông', 'Sợi mì mềm xào bò-giá đỗ bóng xì dầu lửa lớn, món chow fun Quảng Đông khói chảo thơm lừng.', 'chinese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Chow fun","Quảng Đông","Bò","Xào lửa lớn"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a22f9257b0fd7a46', 'ba-chi-kho-dong-pha', 'Ba chỉ kho Đông Pha', 'Khối ba chỉ buộc chỉ hầm Đông Pha hàng giờ với gừng-hành-tương, mềm tan không ngấy, món Hoài Nam trứ danh.', 'chinese', 130, 5, 'hard', '/frigo/illustrations/delicious-meal.png', '["Đông Pha nhục","Trung Hoa","Hầm","Tiệc"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-5f8d0890bd6d0a76', 'vien-su-tu-dau-kho-cai', 'Viên sư tử đầu kho cải', 'Viên thịt lớn mềm như thạch kho trên lớp cải thảo ngọt, món sư tử đầu Hoài Dương sang trọng nhà hàng.', 'chinese', 70, 4, 'hard', '/frigo/illustrations/delicious-meal.png', '["Sư tử đầu","Hoài Dương","Trung Hoa","Nhà hàng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-ece7da4660b63e9d', 'bo-xao-ca-chua-kieu-trung', 'Bò xào cà chua kiểu Trung', 'Bò mềm xào sốt cà chua sánh chua ngọt chan cơm, món nhà Trung Hoa mọi gia đình đều có công thức riêng.', 'chinese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Cà chua","Trung Hoa","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b9d222a8c523b8e4', 'dua-leo-dap-toi-tu-xuyen', 'Dưa leo đập tỏi Tứ Xuyên', 'Dưa leo đập dập thấm tỏi-dầu mè-ớt, món khai vị lạnh Tứ Xuyên giòn sần giải ngấy.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món lạnh","Tứ Xuyên","Khai vị","Giải ngấy"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-51f6c12eefee914d', 'dau-phu-kho-bap-cai', 'Đậu phụ kho bắp cải', 'Đậu phụ kho mềm cùng bắp cải ngọt trong nước tương sánh, món kho thanh đạm kiểu nhà Trung Hoa bình dân.', 'chinese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kho","Đậu phụ","Trung Hoa","Thanh đạm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-6d3fa354c64cf8b1', 'ca-kho-tuong-dam', 'Cá kho tương đậm', 'Khúc cá kho trong nước tương đậm đà thấm thớ, gừng-tỏi ấm nền, món kho mặn ngọt chuẩn vị Trung Hoa.', 'chinese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Kho","Trung Hoa","Cá","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-03577e7fa7667ab8', 'canh-chua-cay-trung-hoa', 'Canh chua cay Trung Hoa', 'Súp chua cay hot-and-sour với nấm-đậu phụ-trứng tía, giấm và ớt đánh thức vị giác, món khai vị trứ danh.', 'chinese', 30, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Súp","Chua cay","Trung Hoa","Khai vị"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-62ebe8dd18b15b5e', 'muc-xao-gung-hanh', 'Mực xào gừng hành', 'Khoanh mực giòn ngọt chần sơ xào cùng gừng-hành lá đậm hương, món xào Quảng Đông ra đĩa trong mười phút.', 'chinese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Mực","Quảng Đông","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-d283a9225d6ece09', 'com-ca-hoi-donburi', 'Cơm cá hồi donburi', 'Miếng cá hồi om nhẹ hành tây phủ cơm nóng, rắc hành lá, tô donburi Nhật đủ bữa trong nửa giờ.', 'japanese', 25, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Donburi","Nhật Bản","Cá hồi","Bữa trưa"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-7ed24282981e96f6', 'thit-ba-chi-shogayaki-gung', 'Thịt ba chỉ shogayaki gừng', 'Lát ba chỉ mỏng áp chảo sốt gừng Nhật, kèm bắp cải sợi giòn, món shogayaki cơm trưa kiểu izakaya.', 'japanese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Shogayaki","Nhật Bản","Ba chỉ","Bữa trưa"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-c6e706b483805e44', 'ba-chi-ham-kakuni', 'Ba chỉ hầm kakuni', 'Khối ba chỉ vuông hầm kakuni hàng giờ mềm tan, gừng-hành lá khử béo, món hầm Nagasaki trứ danh cho ngày lễ.', 'japanese', 120, 5, 'hard', '/frigo/illustrations/delicious-meal.png', '["Kakuni","Nhật Bản","Hầm","Tiệc"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-324e0ea2e2f068bf', 'canh-miso-dau-phu-nam', 'Canh miso đậu phụ nấm', 'Hạt miso tan cuối cùng tạo vị umami dịu cùng đậu phụ-nấm, tô canh miso nhà ấm bụng bữa sáng Nhật.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Miso","Nhật Bản","Canh","Bữa sáng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-5507103398040565', 'mi-xao-yakisoba-rau-cu', 'Mì xào yakisoba rau củ', 'Sợi mì yakisoba xào chua ngọt cùng bắp cải-cà rốt và lát ba chỉ, món xào phố Nhật rắc katsuobushi cuối cùng.', 'japanese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Yakisoba","Nhật Bản","Xào","Bữa trưa"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-710fd476f2dddd56', 'com-trung-boc-omurice', 'Cơm trứng bọc omurice', 'Lớp trứng mỏng vàng bọc cơm gà sốt cà chua, rạch mặt trứng chảy nhẹ, món omurice yoshoku được trẻ em yêu thích.', 'japanese', 35, 2, 'medium', '/frigo/illustrations/delicious-meal.png', '["Omurice","Nhật Bản","Trẻ em","Bữa trưa"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-14c8ef999fe47b8f', 'trung-cuon-tamagoyaki', 'Trứng cuộn tamagoyaki', 'Từng lớp trứng mỏng cuộn chặt thành khối tamagoyaki vàng, ruột mềm ẩm sữa, món hộp cơm Nhật kinh điển.', 'japanese', 15, 2, 'medium', '/frigo/illustrations/delicious-meal.png', '["Tamagoyaki","Nhật Bản","Hộp cơm","Trứng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-0841a517e823e3b6', 'ga-nuong-teriyaki-bong', 'Gà nướng teriyaki bóng', 'Đùi gà áp da giòn phủ sốt teriyaki keo bóng tỏa hương gừng-tỏi, món nướng Nhật dễ làm trên chảo dày.', 'japanese', 35, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Teriyaki","Nhật Bản","Nướng","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-6ae7feae7ec0d517', 'ga-xien-yakitori-hanh', 'Gà xiên yakitori hành', 'Xiên gà-da xen hành lá quét sốt teriyaki trên than, món yakitori phố Nhật khó cưỡng cho buổi tối.', 'japanese', 35, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Yakitori","Nhật Bản","Nướng","Món nhậu"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-7facaaeafc40dac2', 'ca-hoi-nuong-muoi-chanh', 'Cá hồi nướng muối chanh', 'Miếng cá hồi dày nướng muối thô da giòn, vắt chanh tươi cuối cùng, món shioyaki nhẹ bụng chuẩn Nhật.', 'japanese', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Shioyaki","Nhật Bản","Cá hồi","Nhẹ bụng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-70379b3f30b48438', 'goi-dua-leo-tom-nhat', 'Gỏi dưa leo tôm Nhật', 'Dưa leo muối nhanh giòn mát trộn tôm trong nước giấm ngọt thanh, món sunomono khai vị mùa nóng.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Sunomono","Nhật Bản","Khai vị","Mát lành"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-49262ac40836045a', 'trung-hap-chawanmushi-ga', 'Trứng hấp chawanmushi gà', 'Trứng hấp chawanmushi mượt như pudding mặn trong chén sứ, nhân gà-nấm ẩn dưới mặt láng, món hấp tinh tế Nhật.', 'japanese', 35, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Chawanmushi","Nhật Bản","Hấp","Tinh tế"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-e26d04bf95bcede8', 'mi-ramen-heo-trung', 'Mì ramen heo trứng', 'Tô ramen nhà nước dùng ngọt từ ba chỉ hầm, mì dai trứng lòng đào, hành lá-tỏi phi đậm hương phố Osaka.', 'japanese', 55, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Ramen","Nhật Bản","Nước dùng","Bữa tối"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b808fb03d1e8ede6', 'com-ca-ri-ga-nhat', 'Cơm cà ri gà Nhật', 'Sốt cà ri Nhật sánh vàng ngọt dịu ôm lấy gà-cà rốt-hành, chan cơm trắng nóng, món cà ri nhà bất hủ.', 'japanese', 50, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cà ri","Nhật Bản","Cơm","Bữa tối"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-46c2a1c4cc7a8bb5', 'mi-udon-bo-hanh', 'Mì udon bò hành', 'Sợi udon dày dai trong nước dùng ngọt hành tây, lát bò mỏng chần tái, tô niku udon ấm bụng chiều mưa.', 'japanese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Udon","Nhật Bản","Bò","Bữa trưa"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-38fb8569664d1f3b', 'ca-hoi-ap-chao-bo-chanh', 'Cá hồi áp chảo bơ chanh', 'Miếng cá hồi da giòn tắm trong bơ sủi bọt vắt chanh, món meunière Nhật tinh tế chỉ mười lăm phút.', 'japanese', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Meunière","Nhật Bản","Cá hồi","Bơ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-eae128801c2c7f96', 'rau-bina-tron-me-nhat', 'Rau bina trộn mè Nhật', 'Rau bina chần xanh mướt trộn mè rang xay ngọt mặn, món goma-ae phụ nhỏ làm bàn ăn Nhật trọn vị.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Goma-ae","Nhật Bản","Món phụ","Rau xanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-56ec9eae817af509', 'bap-cai-tron-me-lanh', 'Bắp cải trộn mè lạnh', 'Bắp cải sợi giòn mát trộn mè rang xay sốt ngọt mặn, món phụ lạnh nhanh gọn làm bàn ăn Nhật đủ vị.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món phụ","Mè","Mát lành","Nhật Bản"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-44b1338a7a49098d', 'canh-kimchi-dau-phu-han', 'Canh kim chi đậu phụ Hàn', 'Kim chi chín xào ra nước đỏ cay đậm, đậu phụ non thấm sốt trong canh sôi, tô kimchi jjigae quốc dân Hàn Quốc.', 'korean', 35, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kimchi jjigae","Hàn Quốc","Cay","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a24a701c584d3ef3', 'com-tron-bibimbap-han', 'Cơm trộn bibimbap Hàn', 'Từng loại rau xào riêng xếp lên cơm nóng với bò-bòng? bò ướp và trứng lòng đào, trộn đều sốt gochujang cay ngọt, tô bibimbap sắc màu Hàn Quốc.', 'korean', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Bibimbap","Hàn Quốc","Sắc màu","Cơm trộn"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-52b5963c6cecfb96', 'bo-nuong-bulgogi-ngot', 'Bò nướng bulgogi ngọt', 'Lát bò mỏng ướp hành-tương ngọt nướng cháy cạnh thơm ngọt, món bulgogi Hàn Quốc cuốn rau hoặc chan cơm.', 'korean', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bulgogi","Hàn Quốc","Nướng","Ngọt"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-51b6559bf09bc980', 'canh-tom-nau-bi-do', 'Canh tôm nấu bí đỏ', 'Bí đỏ nấu tan tạo nước canh vàng ngọt tự nhiên cùng tôm tươi, món canh mát nhẹ cho bữa cơm gia đình.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Bí đỏ","Thanh mát","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-81a203668e5e4c1a', 'canh-trung-nam-kim-cham', 'Canh trứng nấm kim châm', 'Trứng rắc hoa vàng trên nước canh nấm kim châm ngọt thanh, món canh nhanh mười phút cho bữa tối.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nấm","Nhanh","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-6c20dba60d77bdfd', 'canh-suon-su-su-non', 'Canh sườn su su non', 'Sườn non hầm mềm ngọt nước cùng su su non trong veo, nồi canh ấm cho bữa tối cả nhà.', 'vietnamese', 70, 5, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Sườn","Hầm","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-734cc9acf8620c69', 'canh-dau-phu-ca-chua-trung', 'Canh đậu phụ cà chua trứng', 'Đậu phụ mềm-cà chua chua nhẹ-trứng hoa vàng trong nồi canh, món canh nhanh vừa lành vừa ấm.', 'vietnamese', 20, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Đậu phụ","Nhanh","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-095cff5e61d32fd9', 'canh-bo-ca-chua-ngot', 'Canh bò cà chua ngọt', 'Lát bò mềm nấu nước cà chua ngọt chua nhẹ, tô canh bò chan cơm ngày mưa đầy đặn.', 'vietnamese', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Bò","Cà chua","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a4822c0a1187e4d7', 'suon-nuong-muoi-ot', 'Sườn nướng muối ớt', 'Khúc sườn non nướng muối-ớt cháy cạnh, vắt chanh tươi, món nướng đưa cơm cho cuối tuần quây quần.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Nướng","Sườn","Muối ớt","Cuối tuần"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-04514fa34052d242', 'ga-kho-nam-dam', 'Gà kho nấm đậm', 'Đùi gà kho nấm nước màu sánh, nấm hút đậm nước kho thơm, món mặn đưa cơm ngày thường.', 'vietnamese', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kho","Gà","Nấm","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-695f59248dbf4895', 'ca-kho-gung-sa', 'Cá kho gừng sả', 'Khúc cá kho nồi đất với gừng-sả thơm nồng, nước kho mặn ngọt sánh thấm từng thớ, vị miền Trung đậm đà.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Kho","Cá","Gừng sả","Miền Trung"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-208386f834b8da43', 'trung-kho-tuong-keo', 'Trứng kho tương keo', 'Trứng luộc chiên sơ kho tương sánh bóng đậm vị, món mặn nhanh làm cho bữa cơm thêm phần hấp dẫn.', 'vietnamese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kho","Trứng","Tương","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-d1f8ab89051a6336', 'bong-cai-xao-tom-tuoi', 'Bông cải xào tôm tươi', 'Bông cải xanh giòn ngọt xào nhanh cùng tôm tươi cong hồng, món xào thanh cho bữa tối nhẹ nhàng.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Tôm","Rau xanh","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-03c5e6e31e01088d', 'dau-phu-xao-sa-ot', 'Đậu phụ xào sả ớt', 'Đậu phụ vàng cạnh xào sả bầm-ớt thơm nồng nước tương, món mặn chay chay? món chay đậm vị đưa cơm.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Chay","Sả","Đậu phụ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-2862e7aa0ae0d8fe', 'bo-xao-dua-chua-ngot', 'Bò xào dứa chua ngọt', 'Lát bò mềm xào ra nước chua ngọt tự nhiên từ dứa tươi cùng hành tây giòn, món xào Nam Bộ đưa cơm.', 'vietnamese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Bò","Dứa","Chua ngọt"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-aa94e2f8bdf3985f', 'tom-hap-sa-chanh', 'Tôm hấp sả chanh', 'Tôm hấp sả chanh giữ trọn vị ngọt thịt, chấm muối chanh ớt, món hấp mát lành dễ làm trong 20 phút.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hấp","Tôm","Sả","Mát lành"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b55451e6e46a4c13', 'bap-cai-cuon-hap-thit', 'Bắp cải cuộn hấp thịt', 'Lá bắp cải chần mềm cuộn nhân thịt băm-cà rốt hấp chín, nước hấp ngọt thanh, món hấp khéo tay chiêu đãi.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Hấp","Bắp cải","Khéo tay","Bắc Bộ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-500644420438efd3', 'dau-phu-hap-sa', 'Đậu phụ hấp sả', 'Đậu phụ hấp nóng rưới xì dầu hành gừng, món hấp nhẹ bụng thanh đạm cho bữa tối nhẹ nhàng.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hấp","Đậu phụ","Sả","Thanh đạm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-47cbfe72125b811d', 'goi-bo-dua-leo-chanh', 'Gỏi bò dưa leo chanh', 'Bò chần tái thái mỏng trộn dưa leo giòn trong nước chanh mặn ngọt, gỏi khai vị chua cay cuốn hút.', 'vietnamese', 25, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Gỏi","Bò","Chua cay","Khai vị"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-403a1693ea9b3cf8', 'bun-tom-rau-muong-chua-cay', 'Bún tôm rau muống chua cay', 'Tô bún nước chua cay với tôm tươi và rau muống chần, bữa trưa Nam Bộ thanh mát đầy sức sống.', 'vietnamese', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Bún","Tôm","Chua cay","Nam Bộ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-c039dac37b31acdb', 'mi-quang-ga-ta', 'Mì Quảng gà ta', 'Sợi mì vàng dầu áo nước cốt đậm, gà ta xé mềm, rau sống-đậu phộng giòn, tô Mì Quảng chuẩn vị miền Trung.', 'vietnamese', 55, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Mì Quảng","Miền Trung","Gà","Bữa trưa"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-875e99916a13d031', 'pho-chay-nam-dau', 'Phở chay nấm đậu', 'Nước phở chay ngọt từ nấm-hành nướng, đậu phụ chiên vàng bánh phở mềm, tô phở chay thanh tịnh đủ đầy.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Phở chay","Nấm","Thanh tịnh","Bữa sáng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-389f525ea854b373', 'canh-chua-chay-dua-dau', 'Canh chua chay dứa đậu', 'Canh chua chay me-dứa với đậu phụ và giá đỗ, vị chua thanh kích thích vị giác cho mâm cơm chay.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh chua","Chay","Dứa","Nam Bộ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-8301ed8c884fb619', 'cai-bap-xao-nam-chay', 'Cải bắp xào nấm chay', 'Cải bắp giòn ngọt xào cùng nấm nước tương, món chay mặn nhẹ nhanh gọn cho bữa cơm chay ngày rằm.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Chay","Xào","Cải bắp","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-327ffa644fbe1a7d', 'chao-tom-nam-nong', 'Cháo tôm nấm nóng', 'Cháo trắng nấu nhừ với tôm tươi-nấm ngọt, gừng sợi ấm bụng, tô cháo tối ngày mưa trọn vẹn.', 'vietnamese', 40, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cháo","Tôm","Nấm","Ấm bụng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-9aed26098f07c061', 'trung-duc-thit-bam', 'Trứng đúc thịt bằm', 'Trứng đúc thịt hấp bông xốp cắt miếng chấm tương ớt, món nhanh quen thuộc của bữa cơm Việt.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hấp","Trứng","Nhanh","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-24e75cbb2ba569f4', 'banh-trang-tron-rau-cu', 'Bánh tráng trộn rau củ', 'Sợi bánh tráng dai trộn cải-cà rốt chua cay mặn ngọt, món ăn vặt Sài Gòn gây thương nhớ.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Ăn vặt","Bánh tráng","Sài Gòn","Chua cay"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-0bd4954058454e92', 'lau-ga-nam-am', 'Lẩu gà nấm ấm', 'Nồi lẩu gà nấm nước vàng gừng ngọt thanh, nhúng cải-nấm nóng hổi, món lẩu nhỏ ấm cả nhà ngày lành lạnh.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Lẩu","Gà","Nấm","Bắc Bộ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-7fa36d5f0187a86e', 'com-chien-ba-chi-hanh', 'Cơm chiên ba chỉ hành', 'Mỡ ba chỉ chiên giòn cạnh rang cùng cơm nguội hành lá, hạt cơm béo thơm khác hẳn cơm chiên thường.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Ba chỉ","Béo thơm","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-fcf23c737f51ef13', 'com-chien-ca-chua-trung', 'Cơm chiên cà chua trứng', 'Hạt cơm áo sốt cà chua đỏ au với trứng bông vàng, món cơm chiên kiểu Trung giản dị mà nghiện.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Cà chua","Trung Hoa","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
