('imp-b3d9ecb751b0a043', 'bo-xao-hanh-tay-ot', 'Bò xào hành tây ớt', 'Lát bò mềm xào hành tây ngọt và ớt tươi cay nhẹ, sốt xì dầu bóng, món xào Trung đưa cơm kinh điển.', 'chinese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Bò","Hành tây","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-835a527c81a79e9c', 'sup-bap-cai-thit-bam', 'Súp bắp cải thịt bằm', 'Viên thịt bằm mềm trong súp bắp cải trong veo gừng ấm, món súp Trung Hoa giản dị cho tối lạnh.', 'chinese', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp","Bắp cải","Trung Hoa","Ấm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
