('imp-57b4406be05661c7', 'ba-chi-xao-tuong-dau', 'Ba chỉ xào tương đậu', 'Lát ba chỉ mỏng xào giòn quyện tương đậu thơm nồng, món mặn béo giòn không kho nước kiểu Bắc Kinh.', 'chinese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Tương","Ba chỉ","Béo giòn"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
