('imp-2b5b79ba1b622db1', 'canh-cai-thao-tom', 'Canh cải thảo tôm', 'Cải thảo mềm ngọt nấu tôm tươi ra nước canh trong ngọt, món canh mùa đông ấm áp miền Bắc Trung Hoa.', 'chinese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh","Cải thảo","Tôm","Mùa đông"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
