('imp-55201e4225342ca3', 'ca-sot-chua-ngot-trung', 'Cá sốt chua ngọt Trung', 'Khúc cá chiên vàng phủ sốt chua ngọt dứa bóng loáng, món tiệc Quảng Đông quen thuộc ngày sum họp.', 'chinese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Chua ngọt","Quảng Đông","Cá","Tiệc"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-6771c725aa163703', 'dau-phu-lanh-hanh', 'Đậu phụ lạnh hành', 'Đậu phụ nguội mềm mịn trộn hành lá-xì dầu-ớt, món khai vị lạnh mát lành ngày nóng.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món lạnh","Khai vị","Đậu phụ","Mát lành"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-5eb2769876646aae', 'mi-tron-dau-phu-cay', 'Mì trộn đậu phụ cay', 'Mì nguội trộn đậu phụ chiên sợi với xì dầu-ớt cay nhẹ, món trộn nhanh cho bữa trưa bận rộn.', 'chinese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Cay","Nhanh","Bữa trưa"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-87adca15ad4c1369', 'ga-ham-nikujaga-ca-rot', 'Gà hầm nikujaga cà rốt', 'Gà hầm nikujaga ngọt mặn cùng cà rốt-hành tây mềm tan, món hầm nhà Nhật ấm áp mùa lạnh.', 'japanese', 50, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hầm","Nhật Bản","Mùa lạnh","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-62d95da722597187', 'mi-soba-tron-nam-me', 'Mì soba trộn nấm mè', 'Soba lạnh mát dai kiều mạch trộn nấm xào và mè rang thơm, món mì trộn Nhật thanh nhẹ cho trưa hè.', 'japanese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Soba","Nhật Bản","Mè","Bữa trưa"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-d2ab8a9e07388289', 'muc-nuong-teriyaki', 'Mực nướng teriyaki', 'Mực nguyên nướng quét sốt teriyaki bóng ngọt, da cháy cạnh thơm, món nướng Nhật dễ làm trên than nhỏ.', 'japanese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nướng","Teriyaki","Mực","Nhật Bản"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-81ff926a5557c059', 'ca-hoi-nuong-miso', 'Cá hồi nướng miso', 'Cá hồi ướp miso ngọt nướng vàng thơm, món saikyo yaki nhà hàng Nhật dễ làm tại gia.', 'japanese', 35, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Miso","Nhật Bản","Cá hồi","Nướng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-8c6abf9194ba8c45', 'ga-xao-gia-itame', 'Gà xào giá itame', 'Gà mềm xào giá giòn trên lửa lớn nêm nhẹ, món yasai itame Nhật thanh đạm nhanh gọn.', 'japanese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Itame","Nhật Bản","Giá","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b33750551f6ea7fe', 'nam-nuong-bo-shoyu', 'Nấm nướng bơ shoyu', 'Nấm đùi gà nướng chảo nóng với bơ-xì dầu, vị umami béo đậm, món nhậu izakaya chớm tối.', 'japanese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Izakaya","Nhật Bản","Nấm","Bơ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-e9562581c7d79169', 'com-cua-kanimeshi', 'Cơm cua kanimeshi', 'Cơm nấu cùng nước cua ngọt, rắc trứng tơ cua tươi, món kanimeshi Hokkaido ấm áp đậm biển.', 'japanese', 35, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Kanimeshi","Nhật Bản","Cua","Cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-ee7ca138c67f4f24', 'bo-xao-gung-itame', 'Bò xào gừng itame', 'Lát bò mềm xào hành tây-gừng nước sốt mặn ngọt, món gyu itame nhà Nhật thơm ấm chan cơm.', 'japanese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gyu itame","Nhật Bản","Bò","Gừng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-57a8ece15d731efb', 'sup-miso-bap-cai', 'Súp miso bắp cải', 'Canh miso bắp cải với nấm ngọt thanh, hạt tương tan cuối cùng giữ trọn hương, món canh Nhật mỗi ngày.', 'japanese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Miso","Nhật Bản","Bắp cải","Canh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-23a82881883d70fb', 'mi-udon-nam-dau', 'Mì udon nấm đậu', 'Sợi udon dày trong nước nóng ngọt nấm với đậu phụ mềm, tô udon chay thanh mát cho bữa nhẹ.', 'japanese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Udon","Nhật Bản","Chay","Thanh mát"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-85a3d8b84fc0bc05', 'mi-ramen-pho-mai-kim-chi', 'Mì ramen phô mai kim chi', 'Mì ramen nóng chanh? nóng cay với kim chi, trứng và phô mai tan chảy, tô ramyeon phô mai quốc dân Hàn Quốc.', 'korean', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Ramyeon","Hàn Quốc","Phô mai","Cay"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-9d28abab0b8e5619', 'ga-ham-kim-chi', 'Gà hầm kim chi', 'Đùi gà hầm cùng kim chi chín ra sốt đỏ sánh cay nồng, món dak kimchi jjim đậm đà đưa cơm.', 'korean', 50, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hầm","Kim chi","Hàn Quốc","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-2842fe1b767de23d', 'trung-cuon-gyeran-mari', 'Trứng cuộn gyeran mari', 'Trứng cuộn bầu dục vàng óng nhân cà rốt-hành lá, món gyeran mari ngọt nhẹ trong hộp cơm Hàn.', 'korean', 20, 2, 'medium', '/frigo/illustrations/delicious-meal.png', '["Gyeran mari","Hàn Quốc","Hộp cơm","Trứng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-412960b58d00d211', 'sundubu-tom-cay', 'Sundubu tôm cay', 'Đậu phụ non mềm tan trong nồi sundubu cay nồng với tôm-nấm, đập trứng vào cuối cùng, món Hàn ấm tê đầu lưỡi.', 'korean', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Sundubu","Hàn Quốc","Cay","Đậu phụ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-80976e834de46c34', 'japchae-mi-soi-tron', 'Japchae mì sợi trộn', 'Sợi mì khoai dai ngọt trộn riêng từng loại rau-bò xào mè, món japchae Hàn Quốc cho ngày lễ tiệc.', 'korean', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Japchae","Hàn Quốc","Trộn","Ngày lễ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-8608afb7fee8ebc3', 'ba-chi-nuong-samgyeopsal', 'Ba chỉ nướng samgyeopsal', 'Lát ba chỉ dày nướng chảo cháy cạnh vàng ruộm, cuốn kim chi-tỏi chấm dầu mè, món samgyeopsal tiệc nướng Hàn.', 'korean', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Samgyeopsal","Hàn Quốc","Nướng","Tiệc"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-97ba5787e2d4113b', 'canh-tuong-dau-han', 'Canh tương đậu Hàn', 'Canh doenjang nồng nàn hạt tương đậu lên men cùng rau bina-nấm, tô canh ấm trọn vị bàn ăn Hàn.', 'korean', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Doenjang","Hàn Quốc","Canh","Ấm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-96d226a7f4d12156', 'ga-chien-gangjeong-cay', 'Gà chiên gangjeong cay', 'Miếng gà chiên hai lần phủ sốt gangjeong cay ngọt keo bóng rắc mè, món dakgangjeong giòn rụm gây nghiện.', 'korean', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Dakgangjeong","Hàn Quốc","Chiên","Cay ngọt"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-ba1871f088d9a522', 'lau-bulgogi-nam', 'Lẩu bulgogi nấm', 'Nồi jeongol sôi li ti với bò ướp bulgogi, nấm-cải nhúng chín tới, nước lẩu ngọt hành ấm cả bàn tiệc.', 'korean', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Jeongol","Lẩu","Hàn Quốc","Tiệc"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-24fc3ac5cd3ff445', 'com-chien-kim-chi-han', 'Cơm chiên kim chi Hàn', 'Cơm nguội rang với kim chi chua cay và trứng lòng đào, món kimchi bokkeumbap Hàn Quốc mười lăm phút quốc dân.', 'korean', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Kim chi","Hàn Quốc","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-46962ad0d6f6e63b', 'ga-xao-hung-que-pad-krapao', 'Gà xào húng quế pad krapao', 'Gà bằm xào tỏi-ớt hiểm dậy mùi húng quế Thái, chan cơm trắng trứng chiên, món pad krapao đường phố Thái Lan.', 'thai', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad krapao","Thái Lan","Cay","Đường phố"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f8fc539b7aa359ac', 'com-chien-dua-thai', 'Cơm chiên dứa Thái', 'Cơm chiên dứa chín mọng với tôm-trứng trong chảo nóng, khao pad sapparot chua ngọt nhiệt đới Thái Lan.', 'thai', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Dứa","Thái Lan","Chua ngọt"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-e28e249efceacac7', 'larb-heo-chua-cay', 'Larb heo chua cay', 'Thịt bằm xào khô trộn chanh-ớt-gạo rang, món larb Isan cay tê chua gắt chan cơm gạo? chan cơm nếp hoặc cơm trắng.', 'thai', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Larb","Isan","Thái Lan","Chua cay"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-90fc2e140739a7d7', 'tom-yum-ca-nam', 'Tom yum cá nấm', 'Nước tom yum trong đậm sả-chanh-ớt với cá tươi và nấm, chua cay tê chuẩn vị, tô tom yum pla ấm cả người.', 'thai', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Tom yum","Thái Lan","Cá","Chua cay"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-8ebb3021c30c48f8', 'pad-see-ew-ga', 'Pad see ew gà', 'Mì rộng xào xì dầu ngọt với gà và cải trắng, sợi mì bóng ám khói chảo, món pad see ew phố Thái.', 'thai', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad see ew","Thái Lan","Mì xào","Đường phố"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-8e2f2113f406a7d8', 'ga-xien-sate-sa', 'Gà xiên sate sả', 'Xiên gà ướp sả-nghệ? sả và gia vị nướng than thơm lừng, chấm sốt đậu phộng? chấm muối chanh ớt, món sate Thái biến tấu nhà.', 'thai', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Sate","Thái Lan","Nướng","Món nhậu"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-574963de4a60d466', 'ca-hap-chanh-ot-thai', 'Cá hấp chanh ớt Thái', 'Cá nguyên hấp chín trong nước chanh-ớt-tỏi chua tê, rưới nước sốt nóng, món pla neung manao thanh mát Thái Lan.', 'thai', 25, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Pla neung","Thái Lan","Hấp","Chua tê"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-295e7045e644d2ca', 'goi-muc-mi-soi-thai', 'Gỏi mực mì sợi Thái', 'Mực giòn mì sợi trong trộn chanh-ớt-sả chua cay, món yam wun sen lạnh mát mở màn bữa tiệc Thái.', 'thai', 25, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Yam wun sen","Thái Lan","Gỏi","Mát lành"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1);
INSERT INTO recipes (id, slug, title, description, cuisine, cook_time_minutes, servings, difficulty, image_url, tags, source_type, source_reference, verification_state, version) VALUES
('imp-5e0a488541baee5e', 'trung-chien-kai-jeow', 'Trứng chiên kai jeow', 'Trứng chiên Thái phồng mép giòn ruột mềm với ớt-hành lá, món kai jeow mười phút chan cơm sốt ớt? chan cơm nóng.', 'thai', 15, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kai jeow","Thái Lan","Chiên","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-bcc430e4b54c1e65', 'canh-tom-chuet-tom', 'Canh tom chuet tôm', 'Canh trong dịu tôm-cải cà chua không cay, món tom chuet nhẹ nhàng dành cho ngày muốn ấm mà không tê lưỡi.', 'thai', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Tom chuet","Thái Lan","Canh trong","Nhẹ nhàng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-103ea67cd56c9c96', 'mi-y-carbonara-ba-chi', 'Mì Ý carbonara ba chỉ', 'Sợi mì Ý bọc sốt trứng-phô mai kem mượt với ba chỉ giòn, carbonara nhà thay guanciale bằng ba chỉ vẫn đậm Ý.', 'italian', 25, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Carbonara","Ý","Mì Ý","Kem"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-34505f9722b38fc1', 'mi-y-bo-bam-bologna', 'Mì Ý bò bằm Bologna', 'Ragù Bologna hầm lâu với bò-heo bằm và cà chua đậm sánh, phủ mì Ý nóng, món Ý nhà trứ danh chủ nhật.', 'italian', 75, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Ragù","Bologna","Ý","Chủ nhật"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-266d7af134d7286a', 'mi-y-nam-kem', 'Mì Ý nấm kem', 'Nấm đùi gà xào bơ quyện sốt kem sữa bọc sợi mì Ý, món pasta nấm kem ấm áp cho bữa tối nhanh.', 'italian', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pasta","Nấm","Kem","Ý"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-8b2c852ba59f2143', 'risotto-rau-bina-nam', 'Risotto rau bina nấm', 'Gạo nấu thêm dần nước thành risotto kem sánh với nấm vàng bơ và rau bina xanh, món Ý kiên nhẫn đậm dưỡng.', 'italian', 40, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Risotto","Ý","Rau bina","Nấm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-de5ce12092f4f0aa', 'frittata-rau-bina-pho-mai', 'Frittata rau bina phô mai', 'Khối frittata dày trứng-rau bina-phô mai áp mặt dưới vàng, cắt múi tam giác dùng nóng hay nguội đều ngon.', 'italian', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Frittata","Ý","Trứng","Rau xanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b8d2cb0b37dbdb81', 'ga-sot-chanh-bo-y', 'Gà sốt chanh bơ Ý', 'Miếng ức gà áp chảo tắm trong sốt chanh-bơ chua thanh, món pollo al limone Ý nhẹ nhàng sang trọng.', 'italian', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pollo al limone","Ý","Chanh","Bơ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a4d02f2246e0e115', 'ga-cacciatore-nam', 'Gà cacciatore nấm', 'Đùi gà om cà chua-nấm-hành kiểu thợ săn Ý, hương thảo thơm trong nước sốt đỏ đậm, món cacciatore ấm cả nhà.', 'italian', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cacciatore","Ý","Om","Cà chua"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a60814a4aca4143b', 'vien-thit-polpette-ca-chua', 'Viên thịt polpette cà chua', 'Viên bò chiên sơ om mềm trong sốt cà chua ngọt, món polpette Ý chan mì hoặc chấm bánh mì đều tuyệt.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Polpette","Ý","Viên thịt","Cà chua"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-5504378372dc989b', 'sup-minestrone-rau-cu', 'Súp minestrone rau củ', 'Súp rau củ Ý đậm với cà chua-cà rốt-cải bắp và vụn mì nhỏ, tô minestrone ấm áp mùa lạnh.', 'italian', 50, 5, 'easy', '/frigo/illustrations/delicious-meal.png', '["Minestrone","Ý","Súp rau","Mùa lạnh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b6496331f7aa0ee9', 'mi-y-tom-kem-chanh', 'Mì Ý tôm kem chanh', 'Sợi mì Ý quyện sốt kem sữa chua nhẹ với tôm tươi hồng, vắt chanh cuối cùng, món pasta biển thanh mát.', 'italian', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pasta","Tôm","Kem","Biển"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
