('imp-c78c4d4ca35484d3', 'com-nam-han', 'Cơm nấm Hàn', 'Cơm nấu nấm thấm màu nâu thơm ngọt, hạt cơm đậm vị món cơm Hàn nhà ấm áp.', 'korean', 40, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm nấm","Hàn Quốc","Cơm","Ấm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-97c4b38c79bf9f39', 'canh-kimchi-tom', 'Canh kim chi tôm', 'Kim chi jjigae tôm ngọt thay thịt, nồi canh cay ấm tôm-đậu phụ đậm vị biển Hàn.', 'korean', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kimchi jjigae","Tôm","Hàn Quốc","Cay ấm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b855b6ba4a9a3be8', 'tom-yum-tom-nam', 'Tom yum tôm nấm', 'Nước tom yum chua cay tê sả-chanh-ớt với tôm tươi-nấm, món súp trứ danh Thái Lan chan cơm hay dùng riêng.', 'thai', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Tom yum","Thái Lan","Chua cay","Đường phố"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-2b514b564c702ff1', 'tom-nuong-chanh-ot', 'Tôm nướng chanh ớt', 'Tôm nướng cháy cạnh vắt chanh-ớt cay, món nướng Thái nhiệt đới mọng ngọt.', 'thai', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nướng","Tôm","Thái Lan","Cay"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-119da2ec6738c17e', 'ga-hap-chanh-sa', 'Gà hấp chanh sả', 'Đùi gà hấp chanh-sả mềm thơm dậy mùi nhiệt đới, món hấp Thái nhẹ nhàng ăn với cơm.', 'thai', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hấp","Gà","Sả chanh","Thái Lan"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-2fb85e79ab43b8bc', 'goi-bo-nuong-thai', 'Gỏi bò nướng Thái', 'Bò nướng thái mỏng trộn chanh-ớt mắm gạo rang, gỏi nam tok Thái vừa đậm vừa tươi.', 'thai', 35, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Nam tok","Thái Lan","Bò","Gỏi"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-3f14cf8e63967712', 'muc-xao-toi-ot-thai', 'Mực xào tỏi ớt Thái', 'Khoanh mực giòn xào tỏi-ớt hiểm cay nồng, món xào Thái nhanh đậm vị biển.', 'thai', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Mực","Thái Lan","Cay nồng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-244640181aff1fb6', 'nam-nuong-sa', 'Nấm nướng sả', 'Xiên nấm nướng thơm sả quét tương, món chay nướng Thái mát lành đậm hương.', 'thai', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nướng","Nấm","Chay","Thái Lan"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f494a9f384ce66a4', 'cua-xao-cay-thai', 'Cua xào cay Thái', 'Cua xào sốt ớt-tỏi cay đậm poo pad prik, món biển Thái sang trọng đầy dư vị.', 'thai', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Poo pad prik","Thái Lan","Cua","Cay"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-0ec0d1db60dbdc1e', 'com-ga-khao-man-gai', 'Cơm gà khao man gai', 'Cơm nấu nước gà thơm với gà luộc mềm, sốt gừng chấm, ăn kèm dưa leo, món khao man gai Thái kinh điển.', 'thai', 55, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Khao man gai","Thái Lan","Cơm gà","Bữa trưa"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-4316659025be0f91', 'mi-xao-bo-cay-thai', 'Mì xào bò cay Thái', 'Sợi mì xào bò ớt cay nồng pad kee mao biến tấu, món mì Thái nhanh đậm vị.', 'thai', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad kee mao","Thái Lan","Mì xào","Cay"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-0e30c82a4c77802e', 'goi-dau-phu-cay-thai', 'Gỏi đậu phụ cay Thái', 'Đậu phụ chiên giòn trộn chanh-ớt cay tê, gỏi chay Thái mát lạ đầy vị.', 'thai', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi","Chay","Đậu phụ","Thái Lan"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-d005aca18d138bfe', 'tom-xao-hung-que-thai', 'Tôm xào húng quế Thái', 'Tôm xào tỏi-ớt dậy mùi húng quế Thái cuối cùng, pad krapao tôm chan cơm trứng chiên.', 'thai', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad krapao","Tôm","Thái Lan","Húng quế"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a9710414682c8521', 'mi-xao-xi-dau-bo-thai', 'Mì xào xì dầu bò Thái', 'Sợi mì rộng xào xì dầu ngọt với bò-cải, pad see ew bò Thái đường phố đậm đà.', 'thai', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad see ew","Thái Lan","Bò","Mì xào"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-c64c83ef34771b5a', 'canh-nam-sa-thai', 'Canh nấm sả Thái', 'Canh nấm sả chua thanh dịu không cay, canh chay Thái khai vị mát lành dễ làm.', 'thai', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh chay","Nấm","Sả","Thái Lan"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a71f6ef791b463ea', 'goi-tom-sa-chanh', 'Gỏi tôm sả chanh', 'Tôm chần ngọt trộn sả-chanh cay mát, gỏi tôm Thái khai vị mùa nóng đầy sức sống.', 'thai', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gỏi","Tôm","Sả chanh","Thái Lan"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-9236740e2b55e8a1', 'com-chien-ga-thai', 'Cơm chiên gà Thái', 'Cơm chiên gà-ớt khao pad gai cay nhẹ Thái Lan, bữa tối nhanh gọn đậm đường phố.', 'thai', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Khao pad","Thái Lan","Cơm chiên","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1);
