('imp-a1904f60d9f4f10e', 'mi-y-bo-toi', 'Mì Ý bơ tỏi', 'Sợi mì Ý phủ bơ-tỏi mượt béo burro e aglio, món Ý giản dị chuẩn vị mười lăm phút.', 'italian', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Burro e aglio","Ý","Mì Ý","Bơ tỏi"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-cc5f58548e934d9e', 'mi-y-tom-toi-ot', 'Mì Ý tôm tỏi ớt', 'Pasta tôm aglio-olio ớt đỏ lát mỏng, món Ý biển cay nhẹ nhanh gọn tinh tế.', 'italian', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pasta tôm","Ý","Aglio e olio","Biển"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-8fdcddab058d5f65', 'mi-y-sot-ca-chua-tuoi', 'Mì Ý sốt cà chua tươi', 'Sốt cà chua tươi đơn giản bao sợi mì Ý, món pomodoro kinh điển chuẩn vị nước Ý.', 'italian', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pomodoro","Ý","Mì Ý","Kinh điển"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-d4d1de72f13e8f30', 'lasagna-bo-bam', 'Lasagna bò bằm', 'Lớp mì-sốt bò-béchamel-phô mai xếp chồng nướng vàng, đĩa lasagna Bologna sang trọng chủ nhật.', 'italian', 80, 6, 'hard', '/frigo/illustrations/delicious-meal.png', '["Lasagna","Ý","Nướng lò","Chủ nhật"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-3fd9eb5a7c40c3c0', 'risotto-ga-hanh', 'Risotto gà hành', 'Risotto gà-hành kem sánh thêm dần nước, món Ý cần tay đảo kiên nhẫn thành quả xứng đáng.', 'italian', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Risotto","Ý","Gà","Kem sánh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-4c5955ef4919d61a', 'mi-y-cua-ot', 'Mì Ý cua ớt', 'Linguine cua thịt với ớt-tỏi sốt dầu, món pasta biển Ý sang trọng cho tối đặc biệt.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Linguine cua","Ý","Pasta","Biển"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-c398c169dc196c4e', 'tom-nuong-toi-chanh-y', 'Tôm nướng tỏi chanh Ý', 'Tôm nướng bơ-tỏi-chanh gambri vàng thơm, món khai vị Ý biển ngọt mọng.', 'italian', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gamberoni","Ý","Tôm","Khai vị"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-8fcc592ab7250a38', 'bap-cai-om-ca-chua-y', 'Bắp cải om cà chua Ý', 'Bắp cải om mềm ngọt thấm sốt cà chua-tỏi, món rau phụ Ý nhà bếp dân dã.', 'italian', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Om","Bắp cải","Ý","Món phụ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-da0c2dea539000e5', 'frittata-nam-pho-mai', 'Frittata nấm phô mai', 'Frittata dày trứng-nấm-phô mai áp chảo, cắt múi tam giác vàng ruột mềm món Ý sáng muộn.', 'italian', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Frittata","Ý","Nấm","Bữa sáng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-e427b91ce9f574c3', 'sup-nam-kem-y', 'Súp nấm kem Ý', 'Súp nấm xay mịn thêm kem sữa béo ngậy, món khai vị Ý ấm áp mùa mưa.', 'italian', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp","Nấm","Kem","Ý"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f3eb85959cb62d3e', 'sup-ga-rau-cu-y', 'Súp gà rau củ Ý', 'Súp gà rau củ trong veo ấm nhẹ, món súp Ý giản dị cho ngày mệt mỏi.', 'italian', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp","Gà","Rau củ","Ý"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f4c5afa7ccc2a9ed', 'ca-chua-nhoi-thit-nuong', 'Cà chua nhồi thịt nướng', 'Cà chua nhồi thịt-phô mai nướng lò mềm mọng nước, pomodori ripieni Ý đẹp mắt chiêu đãi.', 'italian', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Pomodori ripieni","Ý","Nướng lò","Chiêu đãi"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-0d54a1288223d8ac', 'ga-nuong-bo-toi-y', 'Gà nướng bơ tỏi Ý', 'Đùi gà nướng bơ-tỏi da vàng giòn thơm lừng, món gà Ý đơn giản cho bữa tối ấm cúng.', 'italian', 40, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nướng lò","Gà","Bơ tỏi","Ý"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-70e5e19dd4073b76', 'bo-ham-ca-chua-y', 'Bò hầm cà chua Ý', 'Bò hầm stracotto lâu giờ tan tưa trong sốt cà chua đậm, món Ý mùa lạnh nấu trước ngày sau ngon hơn.', 'italian', 120, 5, 'hard', '/frigo/illustrations/delicious-meal.png', '["Stracotto","Ý","Bò hầm","Mùa lạnh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-500ffbf4fd05f9da', 'mi-y-muc-ot', 'Mì Ý mực ớt', 'Sợi mì Ý trong sốt mực đỏ ớt, calamari pasta biển cay nhẹ chuẩn nhà hàng Ý.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Calamari pasta","Ý","Mực","Cay"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-ebc8bf739393ac91', 'canh-tom-dau-phu', 'Canh tôm đậu phụ', 'Tôm ngọt nấu đậu phụ mềm nước canh trong, món canh nhanh 20 phút cho bữa tối gia đình.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Tôm","Đậu phụ","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-3446b3924b05eb7b', 'canh-bo-bap-cai-ca-rot', 'Canh bò bắp cải cà rốt', 'Canh bò-cải bắp-cà rốt ngọt thanh nước trong, nồi canh ấm đủ chất cho bữa cơm mưa.', 'vietnamese', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Bò","Cải bắp","Nam Bộ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-6e3eb737c7d88a2c', 'ga-kho-trung', 'Gà kho trứng', 'Đùi gà kho trứng luộc nước màu sánh keo, món kho mặn miền Nam bữa nào cũng vét sạch cơm.', 'vietnamese', 40, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kho","Gà","Trứng","Miền Nam"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-6251f57b97918111', 'tom-kho-tuong-dam', 'Tôm kho tương đậm', 'Tôm kho tương keo mặn ngọt đậm đà, món kho nhanh 15 phút cho bữa tối bận rộn.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Kho","Tôm","Tương","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-977a3409383d743f', 'muc-xao-bong-cai', 'Mực xào bông cải', 'Khoanh mực giòn xào bông cải xanh trong veo sốt mặn ngọt, món xào biển nhanh gọn.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Mực","Bông cải","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a4ff266c02427746', 'bong-cai-xao-toi', 'Bông cải xào tỏi', 'Bông cải xanh xào tỏi giữ xanh giòn ngọt, món rau xanh nhanh gọn cho mọi bữa cơm.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Rau xanh","Tỏi","Nhanh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f9f08651bc712e93', 'cha-ca-ha-noi-nghe', 'Chả cá Hà Nội nghệ', 'Cá tẩm nghệ áp chảo thơm vàng với hành lá thì là, chả cá là Vọng trứ danh Hà thành.', 'vietnamese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Chả cá","Hà Nội","Nghệ","Trứ danh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-0d6c454ae1073ef6', 'su-su-hap-toi', 'Su su hấp tỏi', 'Su su hấp mềm ngọt rưới dầu tỏi thơm, món hấp thanh đạm mười lăm phút cho bữa tối nhẹ.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hấp","Su su","Thanh đạm","Dễ nấu"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-4d81607829384874', 'ga-hap-gung-hanh', 'Gà hấp gừng hành', 'Gà hấp gừng-hành lá mềm ẩm giữ nước, món hấp gia đình đơn giản đủ vị ấm bụng.', 'vietnamese', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hấp","Gà","Gừng","Gia đình"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-1b518ba2f068f3ab', 'nom-dua-chua-cay', 'Nộm dứa chua cay', 'Dứa chín bào sợi trộn cà rốt chanh-ớt chua cay, nộm nhiệt đới giải ngấy khai vị mát lành.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nộm","Dứa","Chua cay","Khai vị"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
