('imp-a9d8b4d783b986d1', 'com-tom-sa-thai', 'Cơm tôm sả Thái', 'Cơm rang tôm sả thơm nồng mặn ngọt nhiệt đới, món cơm Thái nhanh gọn đậm vị.', 'thai', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Tôm","Sả","Thái Lan"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-4095c816782acd82', 'salad-ca-chua-cay-thai', 'Salad cà chua cay Thái', 'Cà chua múi trộn chanh-ớt-tỏi cay thanh, salad Thái khai vị mát lạnh ngày nóng.', 'thai', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Salad","Cà chua","Thái Lan","Mát lành"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-0e9c9740a6232263', 'heo-xao-hung-que', 'Heo xào húng quế', 'Heo bằm xào húng quế pad krapao cay nồng chan cơm trứng chiên, món đường phố Thái.', 'thai', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pad krapao","Heo","Thái Lan","Đường phố"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b6d6788784da6342', 'ca-chien-sot-cay-thai', 'Cá chiên sốt cay Thái', 'Cá chiên da giòn phủ sốt cay-tỏi-chanh, món cá Thái đậm vị lạ miệng đưa cơm.', 'thai', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Cá chiên","Sốt cay","Thái Lan","Đậm vị"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-71cac2085659d819', 'ga-xao-dua-thai', 'Gà xào dứa Thái', 'Đùi gà xào dứa chua ngọt nhiệt đới cay nhẹ, món Thái lạ miệng dễ nấu.', 'thai', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Xào","Gà","Dứa","Thái Lan"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-b398545ca76325f1', 'canh-bap-cai-sa-thai', 'Canh bắp cải sả Thái', 'Canh cải bắp sả chua thanh trong veo, canh chay Thái nhẹ nhàng khai vị.', 'thai', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Canh chay","Cải bắp","Sả","Thái Lan"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-9f9a3f24b4141acb', 'cua-chien-toi-ot-thai', 'Cua chiên tỏi ớt Thái', 'Cua chiên giòn tỏi-ớt vàng thơm, món chiên biển Thái giòn cạnh đậm vị.', 'thai', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Chiên","Cua","Tỏi ớt","Thái Lan"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-8fecebfe6dc0f0a2', 'mi-y-rau-bina', 'Mì Ý rau bina', 'Sợi mì Ý trộn rau bina nhuyễn-tỏi-phô mai, món pasta xanh mướt nhanh gọn mát lành.', 'italian', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pasta","Rau bina","Ý","Xanh mướt"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-20d3992a65cb17fd', 'mi-y-ga-nam', 'Mì Ý gà nấm', 'Sợi mì Ý sốt đỏ gà-nấm mềm thơm, món pasta nhà Ý đầy đặn bữa tối.', 'italian', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Pasta","Gà","Nấm","Ý"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-38137393c32d70d7', 'risotto-tom', 'Risotto tôm', 'Risotto tôm hồng kem sánh hạt gạo mềm thấm, món Ý biển cần tay đảo kiên nhẫn.', 'italian', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Risotto","Tôm","Ý","Kem sánh"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-e61010e240534690', 'muc-om-ca-chua-y', 'Mực om cà chua Ý', 'Mực om cà chua-tỏi mềm mọng nước sốt, calamari in umido Ý đậm nhà bếp biển.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Calamari","Ý","Mực om","Cà chua"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-452ef6d0f8ec0de9', 'tom-om-ca-chua-y', 'Tôm om cà chua Ý', 'Tôm om sốt cà chua gamberi al pomodoro chua nhẹ, món Ý biển nhanh gọn tối thường.', 'italian', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Gamberi","Ý","Tôm om","Cà chua"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-f44be7e8c88c20d3', 'sup-ca-hoi-kem-y', 'Súp cá hồi kem Ý', 'Súp cá hồi kem sữa mượt với cà rốt-hành, món Ý ấm áp sang trọng mùa lạnh.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Súp","Cá hồi","Kem","Ý"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-e748a717f7250188', 'salad-ca-hoi-dua-leo', 'Salad cá hồi dưa leo', 'Salad cá hồi trần nhẹ-dưa leo giòn chanh thanh, món khai vị mát lành nhẹ bụng.', 'italian', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Salad","Cá hồi","Mát lành","Ý"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-957396bc647d3798', 'bong-cai-om-ca-chua-y', 'Bông cải om cà chua Ý', 'Bông cải om mềm thấm sốt cà chua-tỏi, món rau phụ Ý ngọt dịu nhanh gọn.', 'italian', 30, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Om","Bông cải","Ý","Món phụ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-c98aa0f1ffe2f469', 'suon-om-ca-chua-y', 'Sườn om cà chua Ý', 'Sườn om lâu sốt cà chua-hành-cà rốt ragu tách xương mềm, món Ý cuối tuần ấm nồng.', 'italian', 110, 5, 'hard', '/frigo/illustrations/delicious-meal.png', '["Ragu","Sườn","Ý","Cuối tuần"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a286f8724d79a504', 'ca-chua-tron-pho-mai', 'Cà chua trộn phô mai', 'Cà chua múi trộn phô mai-tỏi dầu ô liu, món khai vị lạnh Ý mát lành đơn giản.', 'italian', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Khai vị","Cà chua","Phô mai","Ý"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-83ed31fc537569a6', 'bo-cuon-rau-bina-y', 'Bò cuộn rau bina Ý', 'Lát bò cuộn rau bina-phô mai áp chảo involtini, món Ý khéo tay chan sốt đậm.', 'italian', 30, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Involtini","Ý","Bò cuộn","Khéo tay"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-a92103c19952bcf0', 'ga-chien-chanh-y', 'Gà chiên chanh Ý', 'Gà chiên vàng vắt chanh rắc phô mai, món chiên Ý chua béo thanh nhẹ không ngấy.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Chiên","Gà","Chanh","Ý"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-afdcd866c1f92192', 'ca-om-ca-chua-y', 'Cá om cà chua Ý', 'Cá om sốt cà chua-hành mềm mọng, món pesce in umido Ý đậm biển.', 'italian', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Umido","Cá om","Ý","Cà chua"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-6d26ce6b0af4fb79', 'rau-bina-om-kem-y', 'Rau bina om kem Ý', 'Rau bina om kem sữa mềm mượt, món rau phụ Ý béo thanh nhanh gọn.', 'italian', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Om kem","Rau bina","Ý","Món phụ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1),
('imp-bd34e8ea2eaa1cd4', 'sup-bap-cai-y', 'Súp bắp cải Ý', 'Súp bắp cải-hành-cà rốt trong veo thanh ngọt, món súp Ý nhẹ nhàng cho bữa tối mùa lạnh.', 'italian', 35, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Súp","Bắp cải","Ý","Thanh ngọt"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-scale-399-v1', 'reviewed', 1);
