('imp-afdcd866c1f92192_ing_2', 'imp-afdcd866c1f92192', 'TOMATO', 'Cà chua chín', 4, 'piece', 0),
('imp-afdcd866c1f92192_ing_3', 'imp-afdcd866c1f92192', 'ONION', 'Hành tây', 0.5, 'piece', 0),
('imp-afdcd866c1f92192_ing_4', 'imp-afdcd866c1f92192', 'GARLIC', 'Tỏi', 1, 'piece', 0),
('imp-afdcd866c1f92192_ing_5', 'imp-afdcd866c1f92192', 'SCALLION', 'Hành lá', 1, 'bunch', 0),
('imp-6d26ce6b0af4fb79_ing_1', 'imp-6d26ce6b0af4fb79', 'SPINACH', 'Rau bina (cải bó xôi)', 300, 'g', 0),
('imp-6d26ce6b0af4fb79_ing_2', 'imp-6d26ce6b0af4fb79', 'FRESH_MILK', 'Sữa tươi', 200, 'ml', 0),
('imp-6d26ce6b0af4fb79_ing_3', 'imp-6d26ce6b0af4fb79', 'GARLIC', 'Tỏi', 1, 'piece', 0),
