INSERT INTO recipe_steps (id, recipe_id, step_number, instruction, tip, timer_minutes) VALUES
('imp-810c132a4d2cd4e0_step_1', 'imp-810c132a4d2cd4e0', 1, 'Tôm rút chỉ đen, ướp chút muối. Cà chua bổ múi cau, dứa cắt miếng vừa ăn.', NULL, NULL),
('imp-810c132a4d2cd4e0_step_2', 'imp-810c132a4d2cd4e0', 2, 'Phi thơm tỏi băm với dầu ăn, cho cà chua vào xào mềm rồi đổ 1,2 lít nước đun sôi.', NULL, 5),
('imp-810c132a4d2cd4e0_step_3', 'imp-810c132a4d2cd4e0', 3, 'Cho dứa vào nấu 5 phút cho ra vị chua ngọt, nêm nước mắm, đường và muối cho vừa miệng.', NULL, 5),
('imp-810c132a4d2cd4e0_step_4', 'imp-810c132a4d2cd4e0', 4, 'Thả tôm vào nấu 2 phút tới khi tôm đỏ lên, thêm giá đỗ rồi tắt bếp.', NULL, 2),
('imp-810c132a4d2cd4e0_step_5', 'imp-810c132a4d2cd4e0', 5, 'Vắt thêm chanh nếu thích chua gắt, rắc hành lá cắt nhỏ, múc canh nóng dùng với cơm trắng.', 'Cho tôm cuối cùng để tôm không bị dai.', NULL),
('imp-59015074541ba061_step_1', 'imp-59015074541ba061', 1, 'Khổ qua cắt khoanh 4cm, khoét bỏ ruột, ngâm nước muối loãng 10 phút rồi rửa lại cho bớt đắng.', NULL, 10),
('imp-59015074541ba061_step_2', 'imp-59015074541ba061', 2, 'Trộn tôm xay, thịt heo xay với tiêu, nước mắm và hành lá băm, nhồi chặt vào khoanh khổ qua.', NULL, NULL),
('imp-59015074541ba061_step_3', 'imp-59015074541ba061', 3, 'Đun sôi 1,5 lít nước với nấm hương, thả khổ qua vào hầm lửa nhỏ 25 phút tới khi nhân chín mềm.', NULL, 25),
('imp-59015074541ba061_step_4', 'imp-59015074541ba061', 4, 'Nêm nước mắm, muối cho vừa miệng, rắc hành lá cắt nhỏ và tiêu xay, múc canh nóng dùng với cơm.', NULL, NULL),
('imp-9c678f92a5cb0812_step_1', 'imp-9c678f92a5cb0812', 1, 'Bí đao gọt vỏ, bổ dọc bỏ lõi, cắt miếng vừa ăn. Tôm bóc vỏ rút chỉ, để nguyên con.', NULL, NULL),
('imp-9c678f92a5cb0812_step_2', 'imp-9c678f92a5cb0812', 2, 'Đun sôi 1,2 lít nước với hành tây thái múi, cho bí đao vào nấu 8 phút tới khi bí trong lại.', NULL, 8),
('imp-9c678f92a5cb0812_step_3', 'imp-9c678f92a5cb0812', 3, 'Thả tôm vào nấu 3 phút, nêm nước mắm và chút muối cho vừa miệng.', NULL, 3),
('imp-9c678f92a5cb0812_step_4', 'imp-9c678f92a5cb0812', 4, 'Rắc hành lá cắt nhỏ và tiêu xay, múc canh nóng dùng với cơm trắng.', NULL, NULL),
('imp-80ce5736becc08da_step_1', 'imp-80ce5736becc08da', 1, 'Cà chua rửa sạch, cắt múi cau. Trứng gà đánh tan với chút muối.', NULL, NULL),
('imp-80ce5736becc08da_step_2', 'imp-80ce5736becc08da', 2, 'Phi thơm hành lá trắng với dầu ăn, cho cà chua vào xào mềm rồi đổ 1 lít nước đun sôi.', NULL, 5),
('imp-80ce5736becc08da_step_3', 'imp-80ce5736becc08da', 3, 'Nêm nước mắm, chút đường cho dịu vị chua, rồi từ từ rưới trứng vào theo vòng xoáy, khuấy nhẹ.', NULL, 2),
('imp-80ce5736becc08da_step_4', 'imp-80ce5736becc08da', 4, 'Tắt bếp, rắc hành lá cắt nhỏ, múc canh nóng dùng ngay với cơm.', NULL, NULL),
('imp-9473faeacd64d970_step_1', 'imp-9473faeacd64d970', 1, 'Ức gà luộc trong 12 phút với gừng lát, vớt ra xé sợi vừa ăn, giữ lại nước luộc.', NULL, 12),
('imp-9473faeacd64d970_step_2', 'imp-9473faeacd64d970', 2, 'Nấm xé sợi, cà rốt cắt sợi dài. Đun sôi lại 1,2 lít nước luộc gà.', NULL, NULL),
('imp-9473faeacd64d970_step_3', 'imp-9473faeacd64d970', 3, 'Cho nấm và cà rốt vào nấu 6 phút, tiếp theo thả gà xé sợi vào.', NULL, 6),
('imp-9473faeacd64d970_step_4', 'imp-9473faeacd64d970', 4, 'Nêm nước mắm, muối cho vừa miệng, rắc hành lá cắt nhỏ và tiêu xay, múc canh nóng dùng với cơm.', NULL, NULL),
('imp-9ab5767266722397_step_1', 'imp-9ab5767266722397', 1, 'Mực rửa sạch, thái khoanh tròn 2cm. Cà chua cắt múi cau, gừng cắt sợi.', NULL, NULL),
('imp-9ab5767266722397_step_2', 'imp-9ab5767266722397', 2, 'Xào cà chua với chút dầu ăn cho mềm, đổ 1 lít nước đun sôi cùng gừng sợi.', NULL, 5),
('imp-9ab5767266722397_step_3', 'imp-9ab5767266722397', 3, 'Thả mực vào nấu 3 phút tới khi mực cong trắng, nêm nước mắm và muối vừa miệng.', NULL, 3),
('imp-9ab5767266722397_step_4', 'imp-9ab5767266722397', 4, 'Rắc hành lá cắt nhỏ, múc canh nóng dùng ngay với cơm.', NULL, NULL),
('imp-61eac17e8f3042a9_step_1', 'imp-61eac17e8f3042a9', 1, 'Su su gọt vỏ, bổ bốn rồi thái miếng mỏng vừa ăn. Thịt heo xay trộn tiêu, nước mắm, viên tròn vừa ăn.', NULL, NULL),
('imp-61eac17e8f3042a9_step_2', 'imp-61eac17e8f3042a9', 2, 'Đun sôi 1,2 lít nước, thả su su vào nấu 8 phút tới khi su su trong lại.', NULL, 8),
('imp-61eac17e8f3042a9_step_3', 'imp-61eac17e8f3042a9', 3, 'Thả từng viên thịt băm vào nấu 6 phút tới khi viên thịt nổi lên và chín đều.', NULL, 6),
('imp-61eac17e8f3042a9_step_4', 'imp-61eac17e8f3042a9', 4, 'Nêm nước mắm, muối vừa miệng, rắc hành lá cắt nhỏ và tiêu xay, múc canh nóng dùng với cơm.', NULL, NULL),
('imp-ad2b55ed85f0d109_step_1', 'imp-ad2b55ed85f0d109', 1, 'Bắp cải thái sợi vừa ăn, cà rốt bổ lát mỏng. Trứng gà đánh tan với chút muối.', NULL, NULL),
('imp-ad2b55ed85f0d109_step_2', 'imp-ad2b55ed85f0d109', 2, 'Đun sôi 1,2 lít nước, cho bắp cải và cà rốt vào nấu 8 phút tới khi cải mềm ngọt.', NULL, 8),
('imp-ad2b55ed85f0d109_step_3', 'imp-ad2b55ed85f0d109', 3, 'Từ từ rưới trứng vào theo vòng xoáy, đợi trứng cuộn lại rồi nhẹ tay khuấy đều.', NULL, 2),
('imp-ad2b55ed85f0d109_step_4', 'imp-ad2b55ed85f0d109', 4, 'Nêm nước mắm, muối cho vừa miệng, rắc hành lá cắt nhỏ, múc canh nóng dùng với cơm.', NULL, NULL),
('imp-7cfc6a2e9d8bf8a3_step_1', 'imp-7cfc6a2e9d8bf8a3', 1, 'Rau muống nhặt ngọn non, rửa sạch để ráo. Tôm xay trộn tiêu, nước mắm, đánh dính rồi viên tròn.', NULL, NULL),
('imp-7cfc6a2e9d8bf8a3_step_2', 'imp-7cfc6a2e9d8bf8a3', 2, 'Xào cà chua với chút dầu cho mềm, đổ 1,2 lít nước đun sôi.', NULL, 4),
('imp-7cfc6a2e9d8bf8a3_step_3', 'imp-7cfc6a2e9d8bf8a3', 3, 'Thả viên tôm vào nấu 5 phút tới khi nổi lên, tiếp theo thả rau muống vào chần tới lúc vừa chín tới.', NULL, 5),
('imp-7cfc6a2e9d8bf8a3_step_4', 'imp-7cfc6a2e9d8bf8a3', 4, 'Nêm nước mắm, muối vừa miệng, rắc hành lá cắt nhỏ, múc canh nóng dùng với cơm.', NULL, NULL),
('imp-24cdd0b61f9ed162_step_1', 'imp-24cdd0b61f9ed162', 1, 'Cua đồng xay hòa với 1 lít nước, lọc qua rây lấy nước cua, giữ phần gạch riêng.', NULL, NULL),
('imp-24cdd0b61f9ed162_step_2', 'imp-24cdd0b61f9ed162', 2, 'Xào gạch cua với chút dầu cho thơm, thêm cà chua cắt múi xào mềm rồi đổ nước cua vào đun.', NULL, 5),
('imp-24cdd0b61f9ed162_step_3', 'imp-24cdd0b61f9ed162', 3, 'Khi canh sôi nhẹ, thả đậu phụ cắt miếng vào, hạ lửa nhỏ đun 10 phút để gạch tơ nổi lên.', NULL, 10),
('imp-24cdd0b61f9ed162_step_4', 'imp-24cdd0b61f9ed162', 4, 'Nêm nước mắm, muối vừa miệng, rắc hành lá cắt nhỏ, múc canh nóng dùng với cơm và cà muối.', NULL, NULL),
('imp-15155ec6cc7b7713_step_1', 'imp-15155ec6cc7b7713', 1, 'Thịt ba chỉ rửa sạch, thái dải dài 5cm. Sả, tỏi, ớt bầm nhuyễn trộn nước mắm, mật ong và tiêu thành sốt ướp.', NULL, NULL),
('imp-15155ec6cc7b7713_step_2', 'imp-15155ec6cc7b7713', 2, 'Ướp ba chỉ tối thiểu 30 phút cho thấm đều gia vị.', NULL, 30),
('imp-15155ec6cc7b7713_step_3', 'imp-15155ec6cc7b7713', 3, 'Nướng ba chỉ trên than hoặc lò nóng 200 độ 20 phút, trở mặt giữa chừng tới khi hai mặt cháy cạnh vàng đẹp.', NULL, 20),
('imp-15155ec6cc7b7713_step_4', 'imp-15155ec6cc7b7713', 4, 'Thái miếng vừa ăn, vắt chanh tươi, dùng nóng với bánh tráng, rau sống và bún.', NULL, NULL),
('imp-363ca9ee2c5f7738_step_1', 'imp-363ca9ee2c5f7738', 1, 'Thịt bò cắt khúc 4cm, ướp tỏi băm, sả đập dập, nước mắm, tiêu và chút đường trong 30 phút.', NULL, 30),
('imp-363ca9ee2c5f7738_step_2', 'imp-363ca9ee2c5f7738', 2, 'Phi thơm hành tây và cà chua cắt múi với dầu ăn, cho thịt bò vào xào săn mặt.', NULL, 6),
('imp-363ca9ee2c5f7738_step_3', 'imp-363ca9ee2c5f7738', 3, 'Đổ nước ngập thịt, đun sôi rồi hạ lửa nhỏ hầm 70 phút, thả cà rốt cắt khúc vào hầm thêm 20 phút.', NULL, 80),
('imp-363ca9ee2c5f7738_step_4', 'imp-363ca9ee2c5f7738', 4, 'Nêm lại nước kho sánh vừa miệng, múc bò kho nóng chan ổ bánh mì hoặc ăn với cơm.', NULL, NULL),
('imp-3ec27a2b8f5e4345_step_1', 'imp-3ec27a2b8f5e4345', 1, 'Đùi gà chặt miếng vừa ăn, ướp gừng băm, nước mắm, đường và tiêu trong 20 phút.', NULL, 15),
('imp-3ec27a2b8f5e4345_step_2', 'imp-3ec27a2b8f5e4345', 2, 'Phi thơm ớt băm với dầu ăn, cho gà vào xào săn rồi đổ nước xâm xấp.', NULL, 5),
('imp-3ec27a2b8f5e4345_step_3', 'imp-3ec27a2b8f5e4345', 3, 'Kho lửa nhỏ 15 phút tới khi nước kho sánh keo bám màu vàng nâu đẹp mắt.', NULL, 15),
('imp-3ec27a2b8f5e4345_step_4', 'imp-3ec27a2b8f5e4345', 4, 'Rắc hành lá cắt nhỏ, dùng nóng với cơm trắng và dưa leo thái lát.', NULL, NULL),
('imp-323aae415415eb28_step_1', 'imp-323aae415415eb28', 1, 'Tôm cắt bớt râu, rửa sạch để ráo. Tiêu xanh đập dập trộn với tỏi băm và nước mắm.', NULL, NULL),
('imp-323aae415415eb28_step_2', 'imp-323aae415415eb28', 2, 'Phi thơm tỏi với dầu ăn, cho tôm vào xào tới khi tôm cong đỏ.', NULL, 4),
('imp-323aae415415eb28_step_3', 'imp-323aae415415eb28', 3, 'Thêm hỗn hợp tiêu xanh, chút đường và nửa chén nước, rim lửa vừa 6 phút tới khi nước keo lại.', NULL, 6),
('imp-323aae415415eb28_step_4', 'imp-323aae415415eb28', 4, 'Vắt chút chanh, rắc hành lá cắt nhỏ, dùng nóng với cơm trắng.', NULL, NULL),
('imp-3f1ad35e1f1ec87f_step_1', 'imp-3f1ad35e1f1ec87f', 1, 'Mực rửa sạch, cắt khoanh 2cm. Dứa bỏ lõi cắt miếng vừa ăn, ớt băm nhuyễn.', NULL, NULL),
('imp-3f1ad35e1f1ec87f_step_2', 'imp-3f1ad35e1f1ec87f', 2, 'Phi thơm tỏi với dầu ăn, cho mực vào xào săn nhanh tay rồi trút ra.', NULL, 3),
('imp-3f1ad35e1f1ec87f_step_3', 'imp-3f1ad35e1f1ec87f', 3, 'Cho dứa vào xào ra nước, nêm nước mắm, đường và ớt rồi cho mực trở lại rim 10 phút tới khi nước keo.', NULL, 10),
('imp-3f1ad35e1f1ec87f_step_4', 'imp-3f1ad35e1f1ec87f', 4, 'Nêm lại vừa miệng, dùng nóng với cơm trắng, ăn kèm dưa leo thái lát.', NULL, NULL),
('imp-64e505d497388f4a_step_1', 'imp-64e505d497388f4a', 1, 'Cá hồi cắt miếng dày 2cm, thấm khô, ướp chút muối và tiêu trong 10 phút.', NULL, 10),
('imp-64e505d497388f4a_step_2', 'imp-64e505d497388f4a', 2, 'Áp chảo cá với dầu ăn, mặt da trước 3 phút tới da giòn vàng rồi trở mặt nấu thêm 2 phút.', NULL, 5),
('imp-64e505d497388f4a_step_3', 'imp-64e505d497388f4a', 3, 'Phi thơm tỏi băm trong chảo, thêm nước mắm, đường và nước cốt chanh đun sánh thành sốt.', NULL, NULL),
('imp-64e505d497388f4a_step_4', 'imp-64e505d497388f4a', 4, 'Rưới sốt tỏi-chanh lên cá, rắc hành lá cắt nhỏ, dùng nóng với cơm hoặc rau luộc.', NULL, NULL),
('imp-6e4c264764981b8b_step_1', 'imp-6e4c264764981b8b', 1, 'Gà cắt miếng vừa ăn, ướp nước mắm, tiêu trong 15 phút. Sả, ớt bầm nhuyễn.', NULL, 15),
('imp-6e4c264764981b8b_step_2', 'imp-6e4c264764981b8b', 2, 'Phi thơm sả-ớt bầm với dầu ăn tới khi vàng thơm, cho gà vào xào săn lửa lớn.', NULL, 3),
('imp-6e4c264764981b8b_step_3', 'imp-6e4c264764981b8b', 3, 'Thêm hành tây cắt múi cau, xào tiếp 3 phút tới khi hành vừa trong.', NULL, 3),
('imp-6e4c264764981b8b_step_4', 'imp-6e4c264764981b8b', 4, 'Nêm lại nước mắm, chút đường cho vừa miệng, múc ra đĩa dùng nóng với cơm.', NULL, NULL),
('imp-53760c13ec1e452b_step_1', 'imp-53760c13ec1e452b', 1, 'Tôm bóc vỏ rút chỉ, ướp chút muối và tiêu. Giá đỗ rửa sạch để ráo.', NULL, NULL),
('imp-53760c13ec1e452b_step_2', 'imp-53760c13ec1e452b', 2, 'Phi thơm tỏi băm với dầu ăn, cho tôm vào xào tới khi tôm cong đỏ.', NULL, 3),
('imp-53760c13ec1e452b_step_3', 'imp-53760c13ec1e452b', 3, 'Thêm giá đỗ và hành lá khúc, xào lửa lớn nhanh tay 2 phút giữ độ giòn.', NULL, 2),
('imp-53760c13ec1e452b_step_4', 'imp-53760c13ec1e452b', 4, 'Nêm nước mắm, chút muối vừa miệng, múc ra đĩa dùng nóng với cơm.', NULL, NULL),
('imp-a47ef9289f5d0136_step_1', 'imp-a47ef9289f5d0136', 1, 'Cà rốt gọt vỏ thái sợi mỏng. Trứng đánh tan với chút muối.', NULL, NULL),
('imp-a47ef9289f5d0136_step_2', 'imp-a47ef9289f5d0136', 2, 'Xào cà rốt với dầu ăn trên lửa vừa 3 phút tới khi sợi cà rốt mềm óng.', NULL, 3),
('imp-a47ef9289f5d0136_step_3', 'imp-a47ef9289f5d0136', 3, 'Đổ trứng vào chảo, đợi bám mặt rồi đảo nhanh tay cho trứng bông vàng quyện cà rốt.', NULL, 2),
('imp-a47ef9289f5d0136_step_4', 'imp-a47ef9289f5d0136', 4, 'Nêm xì dầu, chút muối vừa miệng, rắc hành lá cắt nhỏ, dùng nóng với cơm.', NULL, NULL),
('imp-abdcd797955a6d6a_step_1', 'imp-abdcd797955a6d6a', 1, 'Đậu phụ cắt miếng vuông dày 1cm, ráo nước. Cà chua cắt múi cau.', NULL, NULL),
('imp-abdcd797955a6d6a_step_2', 'imp-abdcd797955a6d6a', 2, 'Chiên đậu phụ với dầu ăn tới khi hai mặt vàng giòn, vớt ra để ráo.', NULL, 6),
('imp-abdcd797955a6d6a_step_3', 'imp-abdcd797955a6d6a', 3, 'Xào cà chua với chút dầu tới nhừ ra sốt, nêm xì dầu, đường và muối rồi cho đậu phụ trở lại xào 3 phút.', NULL, 4),
('imp-abdcd797955a6d6a_step_4', 'imp-abdcd797955a6d6a', 4, 'Rắc hành lá cắt nhỏ, múc ra đĩa dùng nóng với cơm trắng.', NULL, NULL),
('imp-97f26ff4abe44f9b_step_1', 'imp-97f26ff4abe44f9b', 1, 'Trộn cua, thịt heo xay, cà rốt sợi, nấm cắt sợi với trứng, nước mắm và tiêu thành nhân đồng đều.', NULL, NULL),
('imp-97f26ff4abe44f9b_step_2', 'imp-97f26ff4abe44f9b', 2, 'Cuốn từng lớp bánh tráng mềm với hai muỗng nhân thành cuộn dài chặt tay.', NULL, NULL),
('imp-97f26ff4abe44f9b_step_3', 'imp-97f26ff4abe44f9b', 3, 'Chiên nem ngập dầu lửa vừa 8 phút tới vàng sơ, vớt ra để ráo.', NULL, 8),
('imp-97f26ff4abe44f9b_step_4', 'imp-97f26ff4abe44f9b', 4, 'Chiên lại lần hai lửa lớn 3 phút tới vỏ giòn rụm, dùng nóng cuốn rau sống chấm nước mắm chua ngọt.', NULL, 3),
('imp-03cb4c492e643034_step_1', 'imp-03cb4c492e643034', 1, 'Tôm bóc vỏ giữ đuôi, rút chỉ, khứa lưng nhẹ để tôm không cong khi chiên.', NULL, NULL),
('imp-03cb4c492e643034_step_2', 'imp-03cb4c492e643034', 2, 'Trứng đánh bông với hành lá cắt nhỏ, chút nước mắm và tiêu.', NULL, NULL),
('imp-03cb4c492e643034_step_3', 'imp-03cb4c492e643034', 3, 'Đun nóng dầu, cầm đuôi tôm chấm qua lớp trứng rồi thả vào chiên 2 phút mỗi mặt tới viền trứng vàng phồng.', NULL, 4),
('imp-03cb4c492e643034_step_4', 'imp-03cb4c492e643034', 4, 'Vớt tôm ra giấy thấm dầu, dùng nóng với cơm hoặc chấm tương ớt.', NULL, NULL),
('imp-c4a65718d5cd4b3c_step_1', 'imp-c4a65718d5cd4b3c', 1, 'Đậu phụ ép bớt nước nghiền vụn, nấm và cà rốt, bắp cải thái sợi mỏng, xào sơ với xì dầu cho ráo nước.', NULL, NULL),
('imp-c4a65718d5cd4b3c_step_2', 'imp-c4a65718d5cd4b3c', 2, 'Cuốn nhân với bánh tráng mềm thành cuộn nhỏ chặt tay, khâu mép bằng nước bột loãng.', NULL, NULL),
('imp-c4a65718d5cd4b3c_step_3', 'imp-c4a65718d5cd4b3c', 3, 'Chiên chả giò ngập dầu lửa vừa 8 phút tới vỏ vàng giòn, vớt ra giấy thấm dầu.', NULL, 8),
('imp-c4a65718d5cd4b3c_step_4', 'imp-c4a65718d5cd4b3c', 4, 'Dùng nóng cuốn rau sống chấm nước tương pha gừng tỏi ớt.', NULL, NULL),
('imp-f3c2431be267b74d_step_1', 'imp-f3c2431be267b74d', 1, 'Cá làm sạch khứa hai bên, xát muối-gừng đập cho hết tanh. Dứa bỏ lõi cắt miếng mỏng.', NULL, NULL),
('imp-f3c2431be267b74d_step_2', 'imp-f3c2431be267b74d', 2, 'Xếp dứa và gừng lát dưới cá trong đĩa sâu lòng, hấp cách thủy 13 phút tới cá chín tới.', NULL, 13),
('imp-f3c2431be267b74d_step_3', 'imp-f3c2431be267b74d', 3, 'Rưới xì dầu pha chút nước hấp quanh đĩa, rắc hành lá sợi.', NULL, NULL),
('imp-f3c2431be267b74d_step_4', 'imp-f3c2431be267b74d', 4, 'Dùng nóng với cơm trắng, chấm thêm nước hấp chua ngọt.', NULL, NULL),
('imp-6118e8aa010584af_step_1', 'imp-6118e8aa010584af', 1, 'Trứng đánh tan với 300ml nước ấm, nước mắm và chút muối, lọc qua rây cho mịn.', NULL, NULL),
('imp-6118e8aa010584af_step_2', 'imp-6118e8aa010584af', 2, 'Tôm cắt lát mỏng xếp đều trong tô, đổ hỗn hợp trứng vào, phủ màng bọc.', NULL, NULL),
('imp-6118e8aa010584af_step_3', 'imp-6118e8aa010584af', 3, 'Hấp cách thủy lửa nhỏ 12 phút tới mặt trứng se láng, tăm xiên không dính.', NULL, 12),
('imp-6118e8aa010584af_step_4', 'imp-6118e8aa010584af', 4, 'Rắc hành lá cắt nhỏ và tiêu xay, dùng nóng với cơm trắng.', NULL, NULL),
('imp-4ced29ad30507f2c_step_1', 'imp-4ced29ad30507f2c', 1, 'Luộc ba chỉ 15 phút và tôm 3 phút, vớt ra nguội rồi thái lát mỏng, tôm bổ đôi.', NULL, 15),
('imp-4ced29ad30507f2c_step_2', 'imp-4ced29ad30507f2c', 2, 'Dưa leo bỏ hạt thái sợi dài, giá đỗ trần sơ 30 giây, hành lá cắt khúc.', NULL, NULL),
('imp-4ced29ad30507f2c_step_3', 'imp-4ced29ad30507f2c', 3, 'Lướt bánh tráng qua nước, xếp tôm-thịt-rau rồi cuộn chặt thành cuốn tròn đều.', NULL, NULL),
('imp-4ced29ad30507f2c_step_4', 'imp-4ced29ad30507f2c', 4, 'Dùng ngay chấm tương đậu phộng, hoặc để bọc khăn ẩm giữ mềm tới khi dùng.', NULL, NULL),
('imp-3a06ac78b572f3ae_step_1', 'imp-3a06ac78b572f3ae', 1, 'Dưa leo bào vỏ khoét bớt ruột, thái sợi, ướp muối 10 phút rồi vắt ráo.', NULL, 10),
('imp-3a06ac78b572f3ae_step_2', 'imp-3a06ac78b572f3ae', 2, 'Tôm luộc chín, bóc vỏ bổ đôi. Cà rốt bào sợi trộn chung với dưa leo.', NULL, 4),
('imp-3a06ac78b572f3ae_step_3', 'imp-3a06ac78b572f3ae', 3, 'Pha nước mắm chanh tỏi ớt chua cay mặn ngọt cân bằng.', NULL, NULL),
('imp-3a06ac78b572f3ae_step_4', 'imp-3a06ac78b572f3ae', 4, 'Trộn đều nộm với nước sốt, để 5 phút thấm rồi bày ra đĩa dùng mát.', NULL, NULL),
('imp-21f32dccd464c605_step_1', 'imp-21f32dccd464c605', 1, 'Gà chần sơ nước sôi cho sạch, ninh với 2 lít nước, hành nướng, gừng nướng lửa nhỏ 50 phút.', NULL, 50),
('imp-21f32dccd464c605_step_2', 'imp-21f32dccd464c605', 2, 'Vớt gà ra xé sợi, nêm nước lèo nước mắm, muối cho trong vừa miệng.', NULL, NULL),
('imp-21f32dccd464c605_step_3', 'imp-21f32dccd464c605', 3, 'Bánh phở trần qua nước sôi, giá đỗ chần sơ, chanh cắt múi kèm rau.', NULL, NULL),
('imp-21f32dccd464c605_step_4', 'imp-21f32dccd464c605', 4, 'Xếp phở-tôi gà vào tô, chan nước lèo sôi, rắc hành lá, dùng nóng vắt chanh kèm giá.', NULL, NULL),
('imp-ba737c5583985a50_step_1', 'imp-ba737c5583985a50', 1, 'Sả đập dập xào cùng dầu ớt đỏ cho ra màu, lưu lại nửa chén dầu ớt rưới tô.', NULL, NULL),
('imp-ba737c5583985a50_step_2', 'imp-ba737c5583985a50', 2, 'Ninh xương? ninh nước lèo với sả và hành 50 phút, nêm nước mắm-muối đậm đà.', NULL, 50),
('imp-ba737c5583985a50_step_3', 'imp-ba737c5583985a50', 3, 'Bò thái lát mỏng ướp chút dầu ớt, chần nhanh trong nước lèo sôi 30 giây giữ độ tái.', NULL, NULL),
('imp-ba737c5583985a50_step_4', 'imp-ba737c5583985a50', 4, 'Bún trần nóng xếp tô, chan nước lèo, đặt bò lên rưới dầu ớt, dùng với giá-hành lá.', NULL, NULL),
('imp-37a39eaa1edcd2e4_step_1', 'imp-37a39eaa1edcd2e4', 1, 'Luộc ba chỉ 20 phút thái mỏng, tôm bóc vỏ chần sơ giữ nguyên con.', NULL, 20),
('imp-37a39eaa1edcd2e4_step_2', 'imp-37a39eaa1edcd2e4', 2, 'Ninh nước dùng từ nước luộc thịt với hành tây 20 phút, nêm nước mắm-muối thanh ngọt.', NULL, 20),
('imp-37a39eaa1edcd2e4_step_3', 'imp-37a39eaa1edcd2e4', 3, 'Hủ tiếu trần nóng chia tô, xếp tôm-thịt-giá lên trên.', NULL, NULL),
('imp-37a39eaa1edcd2e4_step_4', 'imp-37a39eaa1edcd2e4', 4, 'Chan nước dùng sôi, rắc hành lá-tiêu, dùng nóng vắt chanh và chút ớt thái.', NULL, NULL),
('imp-0efa407066cdc8dd_step_1', 'imp-0efa407066cdc8dd', 1, 'Cá cắt khúc ướp muối-tiêu, chiên sơ hai mặt vàng giữ nguyên hình.', NULL, 8),
('imp-0efa407066cdc8dd_step_2', 'imp-0efa407066cdc8dd', 2, 'Xào cà chua với dầu tới nhừ ra nước đỏ, đổ 1,5 lít nước đun sôi rồi thả cá vào.', NULL, 6),
('imp-0efa407066cdc8dd_step_3', 'imp-0efa407066cdc8dd', 3, 'Ninh lửa nhỏ 15 phút cho cá ra ngọt, nêm nước mắm-chua nhẹ vừa miệng.', NULL, 15),
('imp-0efa407066cdc8dd_step_4', 'imp-0efa407066cdc8dd', 4, 'Bún trần nóng chia tô, chan nước cá-cà chua, rắc hành lá dùng nóng vắt chanh-ớt.', NULL, NULL),
('imp-b6aeb931b882e8a3_step_1', 'imp-b6aeb931b882e8a3', 1, 'Nấu cơm từ gạo vo sạch với lượng nước vừa đủ, để ấm trong nồi.', NULL, NULL),
('imp-b6aeb931b882e8a3_step_2', 'imp-b6aeb931b882e8a3', 2, 'Đậu phụ cắt miếng vuông chiên vàng hai mặt, vớt ra để ráo.', NULL, 6),
('imp-b6aeb931b882e8a3_step_3', 'imp-b6aeb931b882e8a3', 3, 'Xào nấm với tỏi cho ra nước, thêm xì dầu, đường, đậu phụ và nửa chén nước kho 8 phút.', NULL, 8),
('imp-b6aeb931b882e8a3_step_4', 'imp-b6aeb931b882e8a3', 4, 'Nước kho sánh keo thấm đậu, rắc hành lá, múc kho chan cơm nóng dùng ngay.', NULL, NULL),
('imp-f0039d3d3f6299b3_step_1', 'imp-f0039d3d3f6299b3', 1, 'Nấm xé sợi vừa ăn, đậu phụ cắt miếng vuông ráo nước.', NULL, NULL),
('imp-f0039d3d3f6299b3_step_2', 'imp-f0039d3d3f6299b3', 2, 'Phi thơm tỏi với dầu, cho nấm vào xào ra nước rồi thêm xì dầu, đường.', NULL, NULL),
('imp-f0039d3d3f6299b3_step_3', 'imp-f0039d3d3f6299b3', 3, 'Cho đậu phụ vào kho lửa nhỏ 8 phút tới khi tương sánh thấm đều.', NULL, 8),
('imp-f0039d3d3f6299b3_step_4', 'imp-f0039d3d3f6299b3', 4, 'Rắc hành lá, dùng nóng với cơm trắng.', NULL, NULL),
('imp-e771ef1a49b2aeed_step_1', 'imp-e771ef1a49b2aeed', 1, 'Bông cải tách nhánh, chần nước sôi 1 phút vớt ra ngâm nước lạnh giữ xanh.', NULL, 2),
('imp-e771ef1a49b2aeed_step_2', 'imp-e771ef1a49b2aeed', 2, 'Xào nấm với tỏi-dầu 2 phút cho ra hương thơm.', NULL, 2),
('imp-e771ef1a49b2aeed_step_3', 'imp-e771ef1a49b2aeed', 3, 'Thêm bông cải, xì dầu vào xào nhanh 2 phút trên lửa lớn.', NULL, 2),
('imp-e771ef1a49b2aeed_step_4', 'imp-e771ef1a49b2aeed', 4, 'Nêm lại vừa miệng, múc ra đĩa dùng nóng với cơm.', NULL, NULL),
('imp-43e806b28c7b8bb5_step_1', 'imp-43e806b28c7b8bb5', 1, 'Cơm nguội bóp tơi hạt. Tôm bóc vỏ cắt nhỏ, cà rốt thái hạt lự, trứng đánh tan.', NULL, NULL),
('imp-43e806b28c7b8bb5_step_2', 'imp-43e806b28c7b8bb5', 2, 'Chiên trứng nhanh tay thành vụn vàng, trút ra để riêng.', NULL, 2),
('imp-43e806b28c7b8bb5_step_3', 'imp-43e806b28c7b8bb5', 3, 'Xào tôm-cà rốt 2 phút, thêm cơm rang lửa lớn 3 phút tới hạt cơm nhảy tanh tách.', NULL, 5),
('imp-43e806b28c7b8bb5_step_4', 'imp-43e806b28c7b8bb5', 4, 'Cho trứng và giá đỗ vào rang thêm 1 phút, nêm xì dầu? nước mắm-muối vừa miệng, rắc hành lá dùng nóng.', NULL, NULL),
('imp-f92a1c569c245541_step_1', 'imp-f92a1c569c245541', 1, 'Mì trần sơ nước sôi 1 phút vớt ra, trộn chút dầu cho không dính.', NULL, 1),
('imp-f92a1c569c245541_step_2', 'imp-f92a1c569c245541', 2, 'Bò ướp xì dầu-tiêu 10 phút, xào lửa lớn 2 phút rồi trút ra.', NULL, 12),
('imp-f92a1c569c245541_step_3', 'imp-f92a1c569c245541', 3, 'Xào tỏi-cải-cà rốt 2 phút, cho mì và bò trở lại, thêm xì dầu xào đều 2 phút.', NULL, 5),
('imp-f92a1c569c245541_step_4', 'imp-f92a1c569c245541', 4, 'Nêm lại vừa miệng, múc ra đĩa dùng nóng.', NULL, NULL),
('imp-f4665d594d941e4a_step_1', 'imp-f4665d594d941e4a', 1, 'Gạo vo sạch, ninh với 1,8 lít nước và đùi gà lửa nhỏ 35 phút tới gạo nở bông.', NULL, 35),
('imp-f4665d594d941e4a_step_2', 'imp-f4665d594d941e4a', 2, 'Vớt gà ra xé sợi, gừng thái sợi mỏng.', NULL, NULL),
('imp-f4665d594d941e4a_step_3', 'imp-f4665d594d941e4a', 3, 'Cho gà xé và nửa số gừng vào nồi cháo, nêm nước mắm-muối, nấu thêm 5 phút.', NULL, 5),
('imp-f4665d594d941e4a_step_4', 'imp-f4665d594d941e4a', 4, 'Múc cháo ra tô, rắc gừng sợi còn lại-hành lá-tiêu, dùng nóng.', NULL, NULL),
('imp-35164fb31de89c5f_step_1', 'imp-35164fb31de89c5f', 1, 'Ức gà luộc 12 phút nguội rồi xé sợi vừa ăn.', NULL, 12),
('imp-35164fb31de89c5f_step_2', 'imp-35164fb31de89c5f', 2, 'Bắp cải-cà rốt thái sợi mỏng, ướp chút muối 5 phút vắt ráo.', NULL, NULL),
('imp-35164fb31de89c5f_step_3', 'imp-35164fb31de89c5f', 3, 'Pha nước mắm chanh tỏi ớt chua cay mặn ngọt cân bằng.', NULL, NULL),
('imp-35164fb31de89c5f_step_4', 'imp-35164fb31de89c5f', 4, 'Trộn gà-bắp cải-cà rốt với nước sốt, để 5 phút thấm, bày đĩa rắc hành lá dùng mát.', NULL, NULL),
('imp-368d91563cb1879b_step_1', 'imp-368d91563cb1879b', 1, 'Sả đập dập, cà chua cắt múi. Xào cà chua-sả với dầu 3 phút cho ra màu, đổ 2 lít nước đun sôi.', NULL, 6),
('imp-368d91563cb1879b_step_2', 'imp-368d91563cb1879b', 2, 'Nêm nước mắm-đường, vắt chanh tạo vị chua cay đặc trưng, giữ lửa sôi li ti.', NULL, 5),
('imp-368d91563cb1879b_step_3', 'imp-368d91563cb1879b', 3, 'Cá cắt khúc ướp muối, nấm xé sợi, tôm để nguyên bóc vỏ.', NULL, NULL),
('imp-368d91563cb1879b_step_4', 'imp-368d91563cb1879b', 4, 'Thả nấm-cá vào nồi lẩu nấu 5 phút rồi thêm tôm, nhúng thêm rau dùng nóng với bún hoặc mì.', NULL, NULL),
('imp-c52c790faf9281da_step_1', 'imp-c52c790faf9281da', 1, 'Nấm xé sợi, xào với tỏi-dầu 3 phút cho ra hương, đổ 1,8 lít nước đun sôi.', NULL, 5),
('imp-c52c790faf9281da_step_2', 'imp-c52c790faf9281da', 2, 'Nêm xì dầu-đường-muối thanh ngọt, thả cà rốt lát vào 5 phút.', NULL, 5),
('imp-c52c790faf9281da_step_3', 'imp-c52c790faf9281da', 3, 'Xếp bắp cải-đậu phụ vào nồi lẩu, sôi li ti 5 phút.', NULL, 5),
('imp-c52c790faf9281da_step_4', 'imp-c52c790faf9281da', 4, 'Nhúng rau theo món, dùng nóng với bún tươi chấm xì dầu.', NULL, NULL),
('imp-e9678cfa1bc90074_step_1', 'imp-e9678cfa1bc90074', 1, 'Tôm bóc vỏ rút chỉ ướp muối-tiêu. Trứng đánh tan, cà chua cắt múi cau.', NULL, NULL),
('imp-e9678cfa1bc90074_step_2', 'imp-e9678cfa1bc90074', 2, 'Chiên trứng thành bông vàng mềm rồi trút ra.', NULL, 2),
('imp-e9678cfa1bc90074_step_3', 'imp-e9678cfa1bc90074', 3, 'Xào tôm 2 phút tới đổi màu, thêm cà chua xào nhừ ra sốt, nêm xì dầu-đường.', NULL, 4),
('imp-e9678cfa1bc90074_step_4', 'imp-e9678cfa1bc90074', 4, 'Cho trứng trở lại đảo đều 1 phút, rắc hành lá dùng nóng với cơm.', NULL, NULL),
('imp-387c41fb3a0c2297_step_1', 'imp-387c41fb3a0c2297', 1, 'Gà cắt hạt lự ướp xì dầu-tiêu 15 phút. Ớt khô cắt khúc, đậu phộng rang giòn bóc vỏ.', NULL, 15),
('imp-387c41fb3a0c2297_step_2', 'imp-387c41fb3a0c2297', 2, 'Phi ớt khô-tỏi với dầu lửa vừa cho ra hương cay, cho gà vào xào 3 phút.', NULL, 4),
('imp-387c41fb3a0c2297_step_3', 'imp-387c41fb3a0c2297', 3, 'Thêm xì dầu-đường-giấm? sốt mặn ngọt, đảo nhanh cho sốt bao đều miếng gà.', NULL, 2),
('imp-387c41fb3a0c2297_step_4', 'imp-387c41fb3a0c2297', 4, 'Rắc đậu phộng rang-hành lá, đảo thêm 30 giây rồi dùng nóng với cơm.', NULL, NULL),
('imp-f5abd36e99d48d94_step_1', 'imp-f5abd36e99d48d94', 1, 'Đậu phụ cắt hạt lự trần nước muối ấm giữ dáng, để ráo.', NULL, 3),
('imp-f5abd36e99d48d94_step_2', 'imp-f5abd36e99d48d94', 2, 'Xào thịt băm với tỏi-gừng-ớt băm 3 phút cho thơm, thêm xì dầu-đậu bột? sốt tương và nửa chén nước.', NULL, 4),
('imp-f5abd36e99d48d94_step_3', 'imp-f5abd36e99d48d94', 3, 'Cho đậu phụ vào om nhẹ 4 phút, không đảo mạnh để miếng đậu nguyên vẹn.', NULL, 4),
('imp-f5abd36e99d48d94_step_4', 'imp-f5abd36e99d48d94', 4, 'Rắc hành lá-tiêu Tứ Xuyên xay, dùng nóng với cơm trắng.', NULL, NULL),
('imp-242fd73cebd63651_step_1', 'imp-242fd73cebd63651', 1, 'Sườn chặt khúc 4cm luộc sơ 10 phút, ướp trứng-xì dầu rồi chiên ngập dầu vàng giòn.', NULL, 12),
('imp-242fd73cebd63651_step_2', 'imp-242fd73cebd63651', 2, 'Xào tỏi-dứa-cà chua với nước cốt? nước sốt chua ngọt từ giấm-đường-xì dầu tới sánh.', NULL, NULL),
('imp-242fd73cebd63651_step_3', 'imp-242fd73cebd63651', 3, 'Cho sườn vào đảo nhanh cho sốt bám bóng keo mọi mặt.', NULL, 3),
('imp-242fd73cebd63651_step_4', 'imp-242fd73cebd63651', 4, 'Bày ra đĩa dùng nóng với cơm trắng.', NULL, NULL),
('imp-34f3eb2438125614_step_1', 'imp-34f3eb2438125614', 1, 'Bắp cải cắt miếng vuông vừa ăn, rửa sạch để ráo. Tỏi băm nhuyễn.', NULL, NULL),
('imp-34f3eb2438125614_step_2', 'imp-34f3eb2438125614', 2, 'Phi thơm tỏi với dầu lửa lớn, cho bắp cải-cà rốt vào xào nhanh 3 phút.', NULL, 3),
('imp-34f3eb2438125614_step_3', 'imp-34f3eb2438125614', 3, 'Nêm xì dầu-muối-đường, đảo đều 1 phút giữ độ giòn.', NULL, NULL),
('imp-34f3eb2438125614_step_4', 'imp-34f3eb2438125614', 4, 'Múc ra đĩa dùng nóng với cơm.', NULL, NULL),
('imp-2d508cd359edb61c_step_1', 'imp-2d508cd359edb61c', 1, 'Đậu phụ cắt miếng vuông dày, khoét nhẹ giữa đặt tôm băm ướp gừng-muối lên mặt.', NULL, NULL),
('imp-2d508cd359edb61c_step_2', 'imp-2d508cd359edb61c', 2, 'Xếp vào xửng hấp 12 phút tới tôm chín hồng và đậu nóng ráo hơi nước.', NULL, 12),
('imp-2d508cd359edb61c_step_3', 'imp-2d508cd359edb61c', 3, 'Rưới xì dầu pha chút nước hấp, rắc hành lá sợi lên mặt.', NULL, NULL),
('imp-2d508cd359edb61c_step_4', 'imp-2d508cd359edb61c', 4, 'Dùng nóng như món khai vị hoặc ăn với cơm.', NULL, NULL),
('imp-6eaf6ed6d417c52c_step_1', 'imp-6eaf6ed6d417c52c', 1, 'Mực cắt khoanh khứa vằn, thấm khô.', NULL, NULL),
('imp-6eaf6ed6d417c52c_step_2', 'imp-6eaf6ed6d417c52c', 2, 'Chiên ngập dầu 3 phút tới vỏ vàng giòn, vớt ráo.', NULL, 3),
('imp-6eaf6ed6d417c52c_step_3', 'imp-6eaf6ed6d417c52c', 3, 'Phi tỏi-ớt với chút dầu, cho mực vào đảo muối-ớt đều 1 phút.', NULL, 1),
('imp-6eaf6ed6d417c52c_step_4', 'imp-6eaf6ed6d417c52c', 4, 'Rắc hành lá rang, dùng nóng với bia hoặc cơm.', NULL, NULL),
('imp-d90dc5bbe2891a12_step_1', 'imp-d90dc5bbe2891a12', 1, 'Gạo vo ninh 1,2 lít nước 30 phút tới nhừ bông.', NULL, 30),
('imp-d90dc5bbe2891a12_step_2', 'imp-d90dc5bbe2891a12', 2, 'Thịt bằm trộn gừng băm-xì dầu, viên tròn thả vào nấu 5 phút.', NULL, 5),
('imp-d90dc5bbe2891a12_step_3', 'imp-d90dc5bbe2891a12', 3, 'Trứng luộc chín cắt múi cau, gừng thái sợi mỏng.', NULL, NULL),
('imp-d90dc5bbe2891a12_step_4', 'imp-d90dc5bbe2891a12', 4, 'Múc cháo tô, đặt trứng-rắc gừng sợi-hành lá, dùng nóng.', NULL, NULL),
('imp-b23ab24915e52866_step_1', 'imp-b23ab24915e52866', 1, 'Cà rốt hạt lự, tôm cắt nhỏ, thịt bằm tán vụn, trứng đánh tan.', NULL, NULL),
('imp-b23ab24915e52866_step_2', 'imp-b23ab24915e52866', 2, 'Xào thịt bằm-tôm 2 phút, thêm cà rốt xào 1 phút.', NULL, 3),
('imp-b23ab24915e52866_step_3', 'imp-b23ab24915e52866', 3, 'Cho cơm rang lửa lớn 3 phút, rưới trứng đảo bông tơi.', NULL, 4),
('imp-b23ab24915e52866_step_4', 'imp-b23ab24915e52866', 4, 'Nêm xì dầu-muối, rắc hành lá, múc ra dùng nóng.', NULL, NULL),
('imp-e83f58ebb9b02fbd_step_1', 'imp-e83f58ebb9b02fbd', 1, 'Xào thịt bằm với tỏi-ớt tới khô giòn 4 phút, nêm xì dầu.', NULL, 4),
('imp-e83f58ebb9b02fbd_step_2', 'imp-e83f58ebb9b02fbd', 2, 'Pha nước trộn giấm-đường-xì dầu-ớt bột trong tô đáy.', NULL, NULL),
('imp-e83f58ebb9b02fbd_step_3', 'imp-e83f58ebb9b02fbd', 3, 'Mì trần 2 phút tới mềm, vớt vào tô sốt.', NULL, 2),
('imp-e83f58ebb9b02fbd_step_4', 'imp-e83f58ebb9b02fbd', 4, 'Đặt thịt bằm lên, rắc hành lá, trộn đều trước khi ăn.', NULL, NULL),
('imp-04d477399e49fe8e_step_1', 'imp-04d477399e49fe8e', 1, 'Mì trần 1 phút tách sợi, bò ướp xì dầu-tiêu 10 phút.', NULL, 10),
('imp-04d477399e49fe8e_step_2', 'imp-04d477399e49fe8e', 2, 'Xào tỏi-bò lửa lớn 2 phút, trút ra.', NULL, 2),
('imp-04d477399e49fe8e_step_3', 'imp-04d477399e49fe8e', 3, 'Xào mì-giá-hành lá 2 phút, cho bò trở lại rưới xì dầu đảo bóng.', NULL, 3),
('imp-04d477399e49fe8e_step_4', 'imp-04d477399e49fe8e', 4, 'Múc ra đĩa dùng nóng. Bước này thực hiện chậm rãi, khuấy đều tay để nguyên liệu chín đều và thấm vị.', NULL, NULL),
('imp-a22f9257b0fd7a46_step_1', 'imp-a22f9257b0fd7a46', 1, 'Ba chỉ cắt khối vuông buộc chỉ, chần 10 phút sạch bọt.', NULL, 10),
('imp-a22f9257b0fd7a46_step_2', 'imp-a22f9257b0fd7a46', 2, 'Lót gừng-hành đáy nồi, đặt thịt, đổ xì dầu-đường-nước xâm xấp.', NULL, NULL),
('imp-a22f9257b0fd7a46_step_3', 'imp-a22f9257b0fd7a46', 3, 'Hầm lửa nhỏ nhất 90 phút, trở mặt giữa chừng cho màu đều.', NULL, 90),
('imp-a22f9257b0fd7a46_step_4', 'imp-a22f9257b0fd7a46', 4, 'Nước hầm sánh keo, cắt miếng dày chan cơm nóng.', NULL, NULL),
('imp-5f8d0890bd6d0a76_step_1', 'imp-5f8d0890bd6d0a76', 1, 'Thịt bằm trộn trứng-gừng băm-xì dầu-tiêu, đánh dính rồi viên to bằng nắm tay.', NULL, NULL),
('imp-5f8d0890bd6d0a76_step_2', 'imp-5f8d0890bd6d0a76', 2, 'Chiên viên thịt 4 phút cho săn mặt.', NULL, 4),
('imp-5f8d0890bd6d0a76_step_3', 'imp-5f8d0890bd6d0a76', 3, 'Lót cải thảo nồi, đặt viên thịt, đổ nước-xì dầu kho 40 phút lửa nhỏ.', NULL, 40),
('imp-5f8d0890bd6d0a76_step_4', 'imp-5f8d0890bd6d0a76', 4, 'Cải mềm hút nước thịt, múc ra dùng nóng với cơm.', NULL, NULL),
('imp-ece7da4660b63e9d_step_1', 'imp-ece7da4660b63e9d', 1, 'Bò ướp xì dầu-tiêu-dầu 10 phút.', NULL, 10),
('imp-ece7da4660b63e9d_step_2', 'imp-ece7da4660b63e9d', 2, 'Xào bò lửa lớn 2 phút tới đổi màu, trút ra.', NULL, 2),
('imp-ece7da4660b63e9d_step_3', 'imp-ece7da4660b63e9d', 3, 'Xào cà chua nhừ ra sốt 3 phút, nêm xì dầu-đường.', NULL, 3),
('imp-ece7da4660b63e9d_step_4', 'imp-ece7da4660b63e9d', 4, 'Cho bò trở lại đảo 1 phút, rắc hành lá dùng với cơm.', NULL, NULL),
('imp-b9d222a8c523b8e4_step_1', 'imp-b9d222a8c523b8e4', 1, 'Dưa leo đập dập cán dao, cắt khúc, rắc muối 5 phút vắt ráo.', NULL, 5),
('imp-b9d222a8c523b8e4_step_2', 'imp-b9d222a8c523b8e4', 2, 'Tỏi băm-ớt băm trộn xì dầu-đường-dầu mè thành sốt.', NULL, NULL),
('imp-b9d222a8c523b8e4_step_3', 'imp-b9d222a8c523b8e4', 3, 'Trộn dưa leo với sốt cho thấm đều vào chỗ nứt.', NULL, NULL),
('imp-b9d222a8c523b8e4_step_4', 'imp-b9d222a8c523b8e4', 4, 'Để 5 phút thấm thêm, dùng lạnh khai vị.', NULL, NULL),
('imp-51f6c12eefee914d_step_1', 'imp-51f6c12eefee914d', 1, 'Đậu phụ cắt miếng vuông chiên vàng hai mặt, vớt ráo.', NULL, 6),
('imp-51f6c12eefee914d_step_2', 'imp-51f6c12eefee914d', 2, 'Phi tỏi với dầu, thả bắp cải xé miếng xào 2 phút cho mềm sơ.', NULL, 3),
('imp-51f6c12eefee914d_step_3', 'imp-51f6c12eefee914d', 3, 'Cho đậu phụ và xì dầu-đường, nửa chén nước, kho lửa nhỏ 8 phút thấm đều.', NULL, 8),
('imp-51f6c12eefee914d_step_4', 'imp-51f6c12eefee914d', 4, 'Nước kho sánh, rắc hành lá dùng nóng với cơm.', NULL, NULL),
('imp-6d3fa354c64cf8b1_step_1', 'imp-6d3fa354c64cf8b1', 1, 'Cá cắt khúc, thấm khô, chiên sơ hai mặt vàng rồi vớt ra.', NULL, 6),
('imp-6d3fa354c64cf8b1_step_2', 'imp-6d3fa354c64cf8b1', 2, 'Phi thơm gừng sợi-tỏi băm với dầu, thêm xì dầu-đường và nửa chén nước đun sôi.', NULL, NULL),
('imp-6d3fa354c64cf8b1_step_3', 'imp-6d3fa354c64cf8b1', 3, 'Cho cá trở lại kho lửa nhỏ 12 phút, trở nhẹ giữa chừng cho nước kho thấm đều thớ cá.', NULL, 12),
('imp-6d3fa354c64cf8b1_step_4', 'imp-6d3fa354c64cf8b1', 4, 'Nước kho sánh lại, rắc hành lá cắt nhỏ, dùng nóng với cơm trắng.', NULL, NULL),
('imp-03577e7fa7667ab8_step_1', 'imp-03577e7fa7667ab8', 1, 'Đậu phụ cắt sợi, nấm xé sợi, cà rốt thái sợi mỏng. Trứng đánh tan.', NULL, NULL),
('imp-03577e7fa7667ab8_step_2', 'imp-03577e7fa7667ab8', 2, 'Đun sôi 1,3 lít nước với nấm-cà rốt 5 phút, thêm đậu phụ.', NULL, 5),
('imp-03577e7fa7667ab8_step_3', 'imp-03577e7fa7667ab8', 3, 'Nêm xì dầu-giấm-ớt băm tạo vị chua cay tê cân bằng, rưới trứng theo vòng xoáy thành hoa tía.', NULL, 3),
('imp-03577e7fa7667ab8_step_4', 'imp-03577e7fa7667ab8', 4, 'Rắc hành lá-tiêu xay, dùng nóng như khai vị hoặc chan cơm.', NULL, NULL),
('imp-62ebe8dd18b15b5e_step_1', 'imp-62ebe8dd18b15b5e', 1, 'Mực thái khoanh khứa vằn, chần nước sôi 30 giây cho cong rồi vớt ráo.', NULL, NULL),
('imp-62ebe8dd18b15b5e_step_2', 'imp-62ebe8dd18b15b5e', 2, 'Phi gừng sợi với dầu lửa lớn, cho mực vào xào nhanh 2 phút.', NULL, 3),
('imp-62ebe8dd18b15b5e_step_3', 'imp-62ebe8dd18b15b5e', 3, 'Thêm cà rốt lát mỏng-hành lá khúc, rưới xì dầu đảo đều 1 phút.', NULL, 2),
('imp-62ebe8dd18b15b5e_step_4', 'imp-62ebe8dd18b15b5e', 4, 'Múc ra đĩa dùng nóng với cơm, chấm thêm xì dầu nếu thích.', NULL, NULL),
('imp-d283a9225d6ece09_step_1', 'imp-d283a9225d6ece09', 1, 'Nấu cơm từ gạo vo sạch, giữ ấm. Cá hồi cắt miếng vừa ăn, hành tây thái sợi.', NULL, NULL),
('imp-d283a9225d6ece09_step_2', 'imp-d283a9225d6ece09', 2, 'Om hành tây với xì dầu-đường-nước 3 phút cho mềm ngọt.', NULL, 3),
('imp-d283a9225d6ece09_step_3', 'imp-d283a9225d6ece09', 3, 'Thả cá hồi vào om 5 phút tới cá chín tới, nước sốt sánh nhẹ.', NULL, 5),
('imp-d283a9225d6ece09_step_4', 'imp-d283a9225d6ece09', 4, 'Xếp cá-hành lên cơm nóng, chan chút sốt, rắc hành lá dùng ngay.', NULL, NULL),
('imp-7ed24282981e96f6_step_1', 'imp-7ed24282981e96f6', 1, 'Ba chỉ cắt lát mỏng. Gừng băm nhuyễn trộn xì dầu-đường-rượu? rượu mirin thay bằng nước và đường thành sốt gừng.', NULL, NULL),
('imp-7ed24282981e96f6_step_2', 'imp-7ed24282981e96f6', 2, 'Áp chảo ba chỉ lửa vừa 3 phút mỗi mặt tới mép vàng giòn, đổ bớt mỡ.', NULL, 6),
('imp-7ed24282981e96f6_step_3', 'imp-7ed24282981e96f6', 3, 'Rưới sốt gừng vào chảo, lăn đều lát thịt 1 phút cho sốt keo bóng.', NULL, 2),
('imp-7ed24282981e96f6_step_4', 'imp-7ed24282981e96f6', 4, 'Bày cùng bắp cải thái sợi, dùng nóng với cơm trắng.', NULL, NULL),
('imp-c6e706b483805e44_step_1', 'imp-c6e706b483805e44', 1, 'Ba chỉ cuộn tròn buộc chỉ, chần nước sôi 10 phút cho sạch bọt, rửa lại.', NULL, 10),
('imp-c6e706b483805e44_step_2', 'imp-c6e706b483805e44', 2, 'Hầm ba chỉ với nước-gừng lát-hành lá 70 phút lửa nhỏ nhỏ nhất, hớt bọt.', NULL, 70),
('imp-c6e706b483805e44_step_3', 'imp-c6e706b483805e44', 3, 'Thêm xì dầu-đường-rượu? thêm đường thay rượu, hầm tiếp 30 phút tới miếng thịt mềm tăm xuyên easily xuyên qua dễ dàng.', NULL, 30),
('imp-c6e706b483805e44_step_4', 'imp-c6e706b483805e44', 4, 'Cắt khoanh dày, rưới nước hầm sánh, dùng nóng với cơm hoặc kèm mì.', NULL, NULL),
('imp-324e0ea2e2f068bf_step_1', 'imp-324e0ea2e2f068bf', 1, 'Nấm cắt lát mỏng, đậu phụ cắt hạt lự nhỏ.', NULL, NULL);
INSERT INTO recipe_steps (id, recipe_id, step_number, instruction, tip, timer_minutes) VALUES
('imp-324e0ea2e2f068bf_step_2', 'imp-324e0ea2e2f068bf', 2, 'Đun 800ml nước với nấm 3 phút, thả đậu phụ vào 2 phút.', NULL, 5),
('imp-324e0ea2e2f068bf_step_3', 'imp-324e0ea2e2f068bf', 3, 'Hòa miso với chút nước canh rồi đổ lại nồi, không đun sôi lại để giữ hương.', NULL, NULL),
('imp-324e0ea2e2f068bf_step_4', 'imp-324e0ea2e2f068bf', 4, 'Rắc hành lá cắt nhỏ, dùng nóng trước bữa cơm.', NULL, NULL),
('imp-5507103398040565_step_1', 'imp-5507103398040565', 1, 'Mì tách sợi, bắp cải-cà rốt thái sợi, ba chỉ cắt miếng nhỏ.', NULL, NULL),
('imp-5507103398040565_step_2', 'imp-5507103398040565', 2, 'Xào ba chỉ với gừng băm 2 phút cho ra mỡ thơm.', NULL, 2),
('imp-5507103398040565_step_3', 'imp-5507103398040565', 3, 'Thêm bắp cải-cà rốt xào 2 phút rồi cho mì và sốt yakisoba từ xì dầu-đường-giấm? giấm thay bằng chút chanh, xào lửa lớn 3 phút.', NULL, 6),
('imp-5507103398040565_step_4', 'imp-5507103398040565', 4, 'Đảo đều sợi mì bóng gia vị, múc ra đĩa dùng nóng.', NULL, NULL),
('imp-710fd476f2dddd56_step_1', 'imp-710fd476f2dddd56', 1, 'Ức gà cắt hạt lự, hành tây băm. Xào gà-hành 3 phút, thêm cà chua nghiền sốt, nêm xì dầu-đường.', NULL, 5),
('imp-710fd476f2dddd56_step_2', 'imp-710fd476f2dddd56', 2, 'Cho cơm vào xào chung 2 phút cho thấm sốt, múc ra để riêng thành phần nhân.', NULL, 2),
('imp-710fd476f2dddd56_step_3', 'imp-710fd476f2dddd56', 3, 'Đổ trứng đánh vào chảo dầu nóng, dùng đũa cuộn nhanh thành lớp mỏng còn mềm ruột.', NULL, NULL),
('imp-710fd476f2dddd56_step_4', 'imp-710fd476f2dddd56', 4, 'Đặt trứng phủ lên nấm cơm? phủ lên nắm cơm trên đĩa, rạch nhẹ giữa, ketchup kèm bên.', NULL, NULL),
('imp-14c8ef999fe47b8f_step_1', 'imp-14c8ef999fe47b8f', 1, 'Trứng đánh tan với sữa, xì dầu, đường nhẹ và hành lá băm, lọc qua rây cho mịn.', NULL, NULL),
('imp-14c8ef999fe47b8f_step_2', 'imp-14c8ef999fe47b8f', 2, 'Quét dầu chảo chữ nhật, đổ một lớp trứng mỏng, khi mặt còn ướt cuộn về một đầu.', NULL, NULL),
('imp-14c8ef999fe47b8f_step_3', 'imp-14c8ef999fe47b8f', 3, 'Quét dầu lại, đổ lớp trứng kế tiếp nâng cuộn trứng lên, lặp tới hết hỗn hợp thành khối dày.', NULL, 6),
('imp-14c8ef999fe47b8f_step_4', 'imp-14c8ef999fe47b8f', 4, 'Gói khối trứng bằng màng? gói bằng khăn? để nguội rồi? cắt khối trứng thành miếng dày 2cm dùng với cơm.', NULL, NULL),
('imp-0841a517e823e3b6_step_1', 'imp-0841a517e823e3b6', 1, 'Đùi gà ép dẹt, chọc da vài lỗ, ướp chút muối-tiêu 15 phút.', NULL, 15),
('imp-0841a517e823e3b6_step_2', 'imp-0841a517e823e3b6', 2, 'Áp da xuống chảo nóng 8 phút tới da giòn vàng, trở mặt nấu 5 phút.', NULL, 13),
('imp-0841a517e823e3b6_step_3', 'imp-0841a517e823e3b6', 3, 'Pha teriyaki từ xì dầu-đường-gừng-tỏi băm, đổ vào chảo lăn gà 2 phút cho sốt keo bóng.', NULL, 3),
('imp-0841a517e823e3b6_step_4', 'imp-0841a517e823e3b6', 4, 'Thái miếng vừa ăn, rưới sốt còn lại, dùng nóng với cơm và bắp cải luộc.', NULL, NULL),
('imp-6ae7feae7ec0d517_step_1', 'imp-6ae7feae7ec0d517', 1, 'Gà cắt khúc 3cm, hành lá cắt khúc cùng cỡ, xiên so le gà-hành vào que treo.', NULL, NULL),
('imp-6ae7feae7ec0d517_step_2', 'imp-6ae7feae7ec0d517', 2, 'Pha sốt yakitori từ xì dầu-đường-tỏi băm, đun sánh nhẹ.', NULL, NULL),
('imp-6ae7feae7ec0d517_step_3', 'imp-6ae7feae7ec0d517', 3, 'Nướng xiên trên than 10 phút, lật và quét sốt ba lần tới mặt cháy cạnh bóng đẹp.', NULL, 10),
('imp-6ae7feae7ec0d517_step_4', 'imp-6ae7feae7ec0d517', 4, 'Dùng nóng ngay khỏi than, chấm thêm sốt nếu thích.', NULL, NULL),
('imp-7facaaeafc40dac2_step_1', 'imp-7facaaeafc40dac2', 1, 'Cá hồi thấm khô, rắc muối thô hai mặt để 10 phút cho thấm.', NULL, 10),
('imp-7facaaeafc40dac2_step_2', 'imp-7facaaeafc40dac2', 2, 'Nướng lò 220 độ hoặc chảo nướng 8 phút tới da giòn và thịt cá tách lớp.', NULL, 8),
('imp-7facaaeafc40dac2_step_3', 'imp-7facaaeafc40dac2', 3, 'Vắt chanh tươi lên mặt cá, rắc hành lá cắt nhỏ.', NULL, NULL),
('imp-7facaaeafc40dac2_step_4', 'imp-7facaaeafc40dac2', 4, 'Dùng nóng với cơm trắng và súp miso.', NULL, NULL),
('imp-70379b3f30b48438_step_1', 'imp-70379b3f30b48438', 1, 'Dưa leo thái lát mỏng, ướp muối 5 phút rồi vắt ráo nước.', NULL, NULL),
('imp-70379b3f30b48438_step_2', 'imp-70379b3f30b48438', 2, 'Tôm luộc chín bóc vỏ bổ đôi, để nguội.', NULL, 4),
('imp-70379b3f30b48438_step_3', 'imp-70379b3f30b48438', 3, 'Pha nước giấm ngọt từ giấm-đường-xì dầu nhẹ.', NULL, NULL),
('imp-70379b3f30b48438_step_4', 'imp-70379b3f30b48438', 4, 'Trộn dưa leo-tôm với nước giấm, rắc hành lá và mè rang, dùng mát.', NULL, NULL),
('imp-49262ac40836045a_step_1', 'imp-49262ac40836045a', 1, 'Trứng đánh tan với 450ml nước dashi? nước dùng từ nấm-gừng ấm, nêm xì dầu-muối, lọc qua rây.', NULL, NULL),
('imp-49262ac40836045a_step_2', 'imp-49262ac40836045a', 2, 'Gà cắt lát mỏng, nấm thái sợi xếp vào từng chén sứ nhỏ.', NULL, NULL),
('imp-49262ac40836045a_step_3', 'imp-49262ac40836045a', 3, 'Đổ hỗn hợp trứng vào chén, hấp cách thủy lửa nhỏ 15 phút tới mặt se mượt.', NULL, 15),
('imp-49262ac40836045a_step_4', 'imp-49262ac40836045a', 4, 'Rắc hành lá cắt nhỏ, dùng nóng bằng thìa ngay trong chén.', NULL, NULL),
('imp-e26d04bf95bcede8_step_1', 'imp-e26d04bf95bcede8', 1, 'Ba chỉ luộc chín 25 phút thái lát, trứng luộc 6 phút lòng đào bóc vỏ ướp xì dầu.', NULL, 25),
('imp-e26d04bf95bcede8_step_2', 'imp-e26d04bf95bcede8', 2, 'Ninh nước dùng từ nước luộc thịt với tỏi-xì dầu 20 phút, nêm mặn ngọt vừa.', NULL, 20),
('imp-e26d04bf95bcede8_step_3', 'imp-e26d04bf95bcede8', 3, 'Mì trần nước sôi 2 phút vớt ra tô.', NULL, 2),
('imp-e26d04bf95bcede8_step_4', 'imp-e26d04bf95bcede8', 4, 'Chan nước dùng sôi, xếp ba chỉ-trứng-hành lá lên mặt, dùng nóng ngay.', NULL, NULL),
('imp-b808fb03d1e8ede6_step_1', 'imp-b808fb03d1e8ede6', 1, 'Nấu cơm từ gạo vo sạch. Gà cắt miếng vừa, cà rốt-hành tây cắt khúc.', NULL, NULL),
('imp-b808fb03d1e8ede6_step_2', 'imp-b808fb03d1e8ede6', 2, 'Xào hành tây-tỏi 3 phút, thêm gà xào 2 phút tới săn mặt.', NULL, 5),
('imp-b808fb03d1e8ede6_step_3', 'imp-b808fb03d1e8ede6', 3, 'Đổ 800ml nước, nấu 10 phút rồi thêm khối cà ri Nhật đun tan sánh lại.', NULL, 15),
('imp-b808fb03d1e8ede6_step_4', 'imp-b808fb03d1e8ede6', 4, 'Chan cà ri cạnh cơm nóng, dùng ngay khi sốt còn chảy nhẹ.', NULL, NULL),
('imp-46c2a1c4cc7a8bb5_step_1', 'imp-46c2a1c4cc7a8bb5', 1, 'Xào hành tây với gừng-xì dầu 3 phút cho mềm ngọt, đổ 1,2 lít nước đun sôi.', NULL, 4),
('imp-46c2a1c4cc7a8bb5_step_2', 'imp-46c2a1c4cc7a8bb5', 2, 'Nêm nước dùng mặn ngọt cân bằng, thả bò thái mỏng chần 30 giây.', NULL, NULL),
('imp-46c2a1c4cc7a8bb5_step_3', 'imp-46c2a1c4cc7a8bb5', 3, 'Udon trần nước sôi 3 phút tới sợi trong dai, vớt ra tô.', NULL, 3),
('imp-46c2a1c4cc7a8bb5_step_4', 'imp-46c2a1c4cc7a8bb5', 4, 'Chan nước dùng-bò lên mì, rắc hành lá dùng nóng.', NULL, NULL),
('imp-38fb8569664d1f3b_step_1', 'imp-38fb8569664d1f3b', 1, 'Cá thấm khô, rắc muối-tiêu hai mặt.', NULL, NULL),
('imp-38fb8569664d1f3b_step_2', 'imp-38fb8569664d1f3b', 2, 'Áp chảo cá với nửa lượng bơ, da xuống trước 3 phút tới giòn, trở mặt 2 phút.', NULL, 5),
('imp-38fb8569664d1f3b_step_3', 'imp-38fb8569664d1f3b', 3, 'Thêm bơ còn lại, nghiêng chảo thìa bơ sủi liên tục 1 phút, vắt chanh vào.', NULL, 2),
('imp-38fb8569664d1f3b_step_4', 'imp-38fb8569664d1f3b', 4, 'Rưới bơ chanh lên cá, rắc hành lá dùng nóng với rau luộc.', NULL, NULL),
('imp-eae128801c2c7f96_step_1', 'imp-eae128801c2c7f96', 1, 'Rau bina chần nước sôi 40 giây, vớt ngay ngâm nước lạnh giữ xanh, vắt kiệt rồi cắt khúc.', NULL, NULL),
('imp-eae128801c2c7f96_step_2', 'imp-eae128801c2c7f96', 2, 'Mè trắng rang vàng giã thô trộn với xì dầu-đường thành sốt mè.', NULL, NULL),
('imp-eae128801c2c7f96_step_3', 'imp-eae128801c2c7f96', 3, 'Trộn rau bina với sốt mè cho từng cọng áo đều.', NULL, NULL),
('imp-eae128801c2c7f96_step_4', 'imp-eae128801c2c7f96', 4, 'Bày ra đĩa nhỏ rắc hành lá, dùng mát hoặc nhiệt phòng.', NULL, NULL),
('imp-56ec9eae817af509_step_1', 'imp-56ec9eae817af509', 1, 'Bắp cải thái sợi mỏng đều, ngâm nước lạnh 5 phút cho giòn rồi để ráo kỹ.', NULL, 5),
('imp-56ec9eae817af509_step_2', 'imp-56ec9eae817af509', 2, 'Mè trắng rang vàng giã thô, trộn với xì dầu-đường thành sốt mè sánh.', NULL, NULL),
('imp-56ec9eae817af509_step_3', 'imp-56ec9eae817af509', 3, 'Trộn bắp cải với sốt mè cho từng sợi áo đều gia vị.', NULL, NULL),
('imp-56ec9eae817af509_step_4', 'imp-56ec9eae817af509', 4, 'Rắc hành lá cắt nhỏ, dùng mát làm món phụ kèm cơm.', NULL, NULL),
('imp-44b1338a7a49098d_step_1', 'imp-44b1338a7a49098d', 1, 'Xào ba chỉ với tỏi 2 phút cho ra mỡ, thêm kim chi cắt khúc xào 3 phút ra nước đỏ.', NULL, 5),
('imp-44b1338a7a49098d_step_2', 'imp-44b1338a7a49098d', 2, 'Đổ 800ml nước, đun sôi 10 phút cho kim chi nhừ ra vị chua cay.', NULL, 10),
('imp-44b1338a7a49098d_step_3', 'imp-44b1338a7a49098d', 3, 'Thả đậu phụ cắt miếng to, nêm xì dầu, đun thêm 5 phút nhẹ tay.', NULL, 5),
('imp-44b1338a7a49098d_step_4', 'imp-44b1338a7a49098d', 4, 'Rắc hành lá cắt nhỏ, dùng nóng chan cơm trắng.', NULL, NULL),
('imp-a24a701c584d3ef3_step_1', 'imp-a24a701c584d3ef3', 1, 'Nấu cơm. Từng loại rau chần hoặc xào riêng với xì dầu-mè, nêm riêng từng thứ cho đậm nhạt khác nhau.', NULL, 10),
('imp-a24a701c584d3ef3_step_2', 'imp-a24a701c584d3ef3', 2, 'Bò ướp xì dầu-đường-tỏi 10 phút rồi xào nhanh chín tới; nấm đùi gà xào riêng, cà rốt sợi chần sơ.', NULL, 12),
('imp-a24a701c584d3ef3_step_3', 'imp-a24a701c584d3ef3', 3, 'Trứng chiên lòng đào giữ yolk chảy.', NULL, NULL),
('imp-a24a701c584d3ef3_step_4', 'imp-a24a701c584d3ef3', 4, 'Xếp cơm-rau-bò-trứng lên tô, thêm gochujang pha? thêm sốt gochujang trong bước nêm, trộn đều trước khi ăn.', NULL, NULL),
('imp-52b5963c6cecfb96_step_1', 'imp-52b5963c6cecfb96', 1, 'Bò ướp xì dầu-đường-tỏi băm-hành tây sợi trong 20 phút cho mềm thấm.', NULL, 20),
('imp-52b5963c6cecfb96_step_2', 'imp-52b5963c6cecfb96', 2, 'Nướng hoặc áp chảo lửa lớn 3 phút tới bò cháy cạnh ngọt, hành trong veo.', NULL, 4),
('imp-52b5963c6cecfb96_step_3', 'imp-52b5963c6cecfb96', 3, 'Rắc hành lá cắt nhỏ và mè rang.', NULL, NULL),
('imp-52b5963c6cecfb96_step_4', 'imp-52b5963c6cecfb96', 4, 'Dùng nóng cuốn rau xà lách hoặc chan cơm trắng.', NULL, NULL),
('imp-51b6559bf09bc980_step_1', 'imp-51b6559bf09bc980', 1, 'Bí đỏ gọt vỏ bỏ lõi cắt miếng vừa ăn, tôm bóc vỏ rút chỉ.', NULL, NULL),
('imp-51b6559bf09bc980_step_2', 'imp-51b6559bf09bc980', 2, 'Xào hành tây mềm với chút dầu, đổ 1,2 lít nước và bí đỏ nấu 10 phút.', NULL, 10),
('imp-51b6559bf09bc980_step_3', 'imp-51b6559bf09bc980', 3, 'Thả tôm nấu 3 phút, nêm nước mắm-muối cho ngọt thanh.', NULL, 3),
('imp-51b6559bf09bc980_step_4', 'imp-51b6559bf09bc980', 4, 'Rắc hành lá cắt nhỏ, múc canh nóng dùng với cơm.', NULL, NULL),
('imp-81a203668e5e4c1a_step_1', 'imp-81a203668e5e4c1a', 1, 'Nấm kim châm cắt gốc tách sợi, rửa nhẹ để ráo. Trứng đánh tan.', NULL, NULL),
('imp-81a203668e5e4c1a_step_2', 'imp-81a203668e5e4c1a', 2, 'Đun sôi 1 lít nước, thả nấm nấu 4 phút ra vị ngọt.', NULL, 4),
('imp-81a203668e5e4c1a_step_3', 'imp-81a203668e5e4c1a', 3, 'Nêm nước mắm, từ từ rưới trứng khuấy nhẹ thành hoa.', NULL, NULL),
('imp-81a203668e5e4c1a_step_4', 'imp-81a203668e5e4c1a', 4, 'Rắc hành lá, múc canh nóng dùng ngay với cơm.', NULL, NULL),
('imp-6c20dba60d77bdfd_step_1', 'imp-6c20dba60d77bdfd', 1, 'Sườn chặt khúc chần nước sôi 3 phút cho sạch bọt, rửa lại.', NULL, NULL),
('imp-6c20dba60d77bdfd_step_2', 'imp-6c20dba60d77bdfd', 2, 'Hầm sườn với 1,8 lít nước lửa nhỏ 45 phút tới mềm.', NULL, 45),
('imp-6c20dba60d77bdfd_step_3', 'imp-6c20dba60d77bdfd', 3, 'Su su gọt vỏ bổ múi cau, thả vào hầm thêm 10 phút.', NULL, 10),
('imp-6c20dba60d77bdfd_step_4', 'imp-6c20dba60d77bdfd', 4, 'Nêm nước mắm-muối, rắc hành lá, múc canh nóng dùng với cơm.', NULL, NULL),
('imp-734cc9acf8620c69_step_1', 'imp-734cc9acf8620c69', 1, 'Cà chua cắt múi, đậu phụ cắt miếng vuông, trứng đánh tan.', NULL, NULL),
('imp-734cc9acf8620c69_step_2', 'imp-734cc9acf8620c69', 2, 'Xào cà chua mềm ra nước, đổ 1,2 lít nước đun sôi.', NULL, NULL),
('imp-734cc9acf8620c69_step_3', 'imp-734cc9acf8620c69', 3, 'Thả đậu phụ nấu 3 phút, rưới trứng tạo hoa, nêm nước mắm-muối.', NULL, NULL),
('imp-734cc9acf8620c69_step_4', 'imp-734cc9acf8620c69', 4, 'Rắc hành lá, múc canh nóng dùng với cơm.', NULL, NULL),
('imp-095cff5e61d32fd9_step_1', 'imp-095cff5e61d32fd9', 1, 'Bò ướp chút muối-tiêu. Cà chua cắt múi, cà rốt cắt lát.', NULL, NULL),
('imp-095cff5e61d32fd9_step_2', 'imp-095cff5e61d32fd9', 2, 'Xào cà chua mềm ra nước đỏ, đổ 1,3 lít nước và cà rốt nấu 8 phút.', NULL, 8),
('imp-095cff5e61d32fd9_step_3', 'imp-095cff5e61d32fd9', 3, 'Thả bò nấu 3 phút tới vừa chín, nêm nước mắm-đường nhẹ.', NULL, NULL),
('imp-095cff5e61d32fd9_step_4', 'imp-095cff5e61d32fd9', 4, 'Rắc hành lá, múc canh nóng chan cơm trắng.', NULL, NULL),
('imp-a4822c0a1187e4d7_step_1', 'imp-a4822c0a1187e4d7', 1, 'Sườn chặt khúc dài, ướp tỏi-ớt băm-nước mắm-tiêu 25 phút.', NULL, 25),
