('imp-a4822c0a1187e4d7_step_4', 'imp-a4822c0a1187e4d7', 4, 'Vắt chanh tươi lên, dùng nóng với cơm và rau sống.', NULL, NULL),
('imp-04514fa34052d242_step_1', 'imp-04514fa34052d242', 1, 'Gà chặt miếng ướp nước mắm-đường-tiêu 15 phút.', NULL, 15),
