('imp-2862e7aa0ae0d8fe_step_1', 'imp-2862e7aa0ae0d8fe', 1, 'Bò ướp nước mắm-tiêu 10 phút, dứa bỏ lõi cắt miếng, hành tây múi cau.', NULL, 10),
