('imp-aac2c265c3845ec4_step_1', 'imp-aac2c265c3845ec4', 1, 'Tôm rạch lưng rút chỉ, xếp đĩa với gừng sợi.', NULL, NULL),
('imp-aac2c265c3845ec4_step_2', 'imp-aac2c265c3845ec4', 2, 'Hấp 6 phút tới tôm cong hồng chín tới.', NULL, 6),
