('imp-55201e4225342ca3_step_4', 'imp-55201e4225342ca3', 4, 'Bày ra đĩa dùng nóng với cơm trắng.', NULL, NULL),
('imp-6771c725aa163703_step_1', 'imp-6771c725aa163703', 1, 'Đậu phụ trần nước sôi 2 phút cho chắc mặt, để nguội hoàn toàn.', NULL, 2),
