('imp-87adca15ad4c1369_step_1', 'imp-87adca15ad4c1369', 1, 'Gà cắt miếng, cà rốt thái khúc, hành tây bổ múi cau.', NULL, NULL),
('imp-87adca15ad4c1369_step_2', 'imp-87adca15ad4c1369', 2, 'Xào gà 2 phút săn, thêm hành tây-cà rốt đảo 2 phút.', NULL, 4),
('imp-87adca15ad4c1369_step_3', 'imp-87adca15ad4c1369', 3, 'Đổ nước xâm xấp cùng xì dầu-đường, hầm lửa nhỏ 30 phút tới mềm thấm.', NULL, 30),
