('imp-62d95da722597187_step_1', 'imp-62d95da722597187', 1, 'Soba trần 3 phút vừa mềm, xả nước lạnh giữ dai.', NULL, 3),
('imp-62d95da722597187_step_2', 'imp-62d95da722597187', 2, 'Xào nấm với chút dầu 2 phút, nêm xì dầu-đường nhẹ.', NULL, 2),
