('imp-80976e834de46c34_step_2', 'imp-80976e834de46c34', 2, 'Xào riêng: rau bina, cà rốt sợi, nấm sợi và bò ướp xì dầu — mỗi thứ giữ vị riêng.', NULL, 10),
('imp-80976e834de46c34_step_3', 'imp-80976e834de46c34', 3, 'Trộn tất cả với mì, nêm xì dầu-đường-mè rang cho hài hòa.', NULL, NULL),
