('imp-8608afb7fee8ebc3_step_1', 'imp-8608afb7fee8ebc3', 1, 'Ba chỉ cắt lát dày 1cm. Kim chi cắt khúc xào sơ cạnh chảo cùng tỏi lát.', NULL, NULL),
