('imp-8608afb7fee8ebc3_step_4', 'imp-8608afb7fee8ebc3', 4, 'Cuốn thịt-kim chi chấm dầu mè-tiêu, dùng nóng ngay.', NULL, NULL),
('imp-97ba5787e2d4113b_step_1', 'imp-97ba5787e2d4113b', 1, 'Đun 800ml nước với nấm-tỏi lát 4 phút cho ra nước ngọt.', NULL, 4),
