('imp-cd86ce166f002f60_step_3', 'imp-cd86ce166f002f60', 3, 'Hầm lửa nhỏ 50 phút tới sườn mềm tách xương, nước sánh đậm.', NULL, 50),
('imp-cd86ce166f002f60_step_4', 'imp-cd86ce166f002f60', 4, 'Rắc hành lá, dùng nóng với cơm.', NULL, NULL),
('imp-3e8e08fb584de7f3_step_1', 'imp-3e8e08fb584de7f3', 1, 'Bò cắt khối 4cm chần nước sôi 3 phút, rửa sạch.', NULL, NULL),
('imp-3e8e08fb584de7f3_step_2', 'imp-3e8e08fb584de7f3', 2, 'Xào gừng xắt lát với dầu, cho bò xào săn, đổ nước ngập hầm 60 phút lửa nhỏ.', NULL, 60),
('imp-3e8e08fb584de7f3_step_3', 'imp-3e8e08fb584de7f3', 3, 'Thả cà rốt khúc, nêm xì dầu-đường hầm thêm 25 phút.', NULL, 25);
INSERT INTO recipe_steps (id, recipe_id, step_number, instruction, tip, timer_minutes) VALUES
('imp-3e8e08fb584de7f3_step_4', 'imp-3e8e08fb584de7f3', 4, 'Nước hầm sánh, rắc hành lá dùng nóng với cơm.', NULL, NULL),
('imp-abcc9b72400680cf_step_1', 'imp-abcc9b72400680cf', 1, 'Trứng đánh tan với hành lá băm, xì dầu nhẹ.', NULL, NULL),
('imp-abcc9b72400680cf_step_2', 'imp-abcc9b72400680cf', 2, 'Đổ trứng vào chảo nóng dầu mỏng, lắc đều thành lớp mỏng.', NULL, NULL),
('imp-abcc9b72400680cf_step_3', 'imp-abcc9b72400680cf', 3, 'Khi mặt se, cuộn từ mép thành cuộn dẹt, lật chín đều.', NULL, 4),
('imp-abcc9b72400680cf_step_4', 'imp-abcc9b72400680cf', 4, 'Cắt khoanh dày 2cm, bày đĩa dùng nóng.', NULL, NULL),
('imp-26359a897d4be366_step_1', 'imp-26359a897d4be366', 1, 'Nấm cắt lát, gừng sợi, tôm bóc vỏ rút chỉ.', NULL, NULL),
('imp-26359a897d4be366_step_2', 'imp-26359a897d4be366', 2, 'Đun 1,2 lít nước với gừng 4 phút, thả nấm nấu 4 phút.', NULL, 8),
('imp-26359a897d4be366_step_3', 'imp-26359a897d4be366', 3, 'Thả tôm nấu 3 phút, nêm xì dầu-muối thanh.', NULL, 3),
('imp-26359a897d4be366_step_4', 'imp-26359a897d4be366', 4, 'Rắc hành lá, múc súp nóng làm khai vị.', NULL, NULL),
('imp-00e0b1417e11b291_step_1', 'imp-00e0b1417e11b291', 1, 'Đậu phụ cắt miếng vuông chiên vàng hai mặt.', NULL, NULL),
('imp-00e0b1417e11b291_step_2', 'imp-00e0b1417e11b291', 2, 'Phi tỏi, xào hành tây múi cau 2 phút trong veo.', NULL, NULL),
('imp-00e0b1417e11b291_step_3', 'imp-00e0b1417e11b291', 3, 'Cho đậu phụ vào rưới xì dầu-đường, xào 3 phút thấm sốt.', NULL, NULL),
('imp-00e0b1417e11b291_step_4', 'imp-00e0b1417e11b291', 4, 'Rắc hành lá, múc ra đĩa dùng nóng với cơm.', NULL, NULL),
('imp-45274582db71eb9f_step_1', 'imp-45274582db71eb9f', 1, 'Mì trần 1 phút trộn dầu chống dính, tôm bóc vỏ rút chỉ.', NULL, NULL),
('imp-45274582db71eb9f_step_2', 'imp-45274582db71eb9f', 2, 'Xào tỏi-tôm 2 phút tới cong hồng, trút ra.', NULL, NULL),
('imp-45274582db71eb9f_step_3', 'imp-45274582db71eb9f', 3, 'Xào cải sợi 1 phút, cho mì-tôm trở lại rưới xì dầu xào bóng 2 phút.', NULL, NULL),
('imp-45274582db71eb9f_step_4', 'imp-45274582db71eb9f', 4, 'Rắc hành lá, múc ra đĩa dùng nóng.', NULL, NULL),
('imp-3d2e5735cbfe9654_step_1', 'imp-3d2e5735cbfe9654', 1, 'Tôm cắt râu rạch lưng, thấm khô rắc muối-tiêu.', NULL, NULL),
('imp-3d2e5735cbfe9654_step_2', 'imp-3d2e5735cbfe9654', 2, 'Phi tỏi-ớt băm với dầu, cho tôm rang lửa lớn 5 phút tới vỏ giòn đỏ.', NULL, 6),
('imp-3d2e5735cbfe9654_step_3', 'imp-3d2e5735cbfe9654', 3, 'Rắc muối tiêu xay thêm, đảo nhanh cho bám đều.', NULL, NULL),
('imp-3d2e5735cbfe9654_step_4', 'imp-3d2e5735cbfe9654', 4, 'Rắc hành lá, dùng nóng ăn cả vỏ.', NULL, NULL),
('imp-73568e9a99d0ccdf_step_1', 'imp-73568e9a99d0ccdf', 1, 'Trứng đánh tan muối nhẹ, hành tây thái múi mỏng.', NULL, NULL),
('imp-73568e9a99d0ccdf_step_2', 'imp-73568e9a99d0ccdf', 2, 'Xào hành tây 2 phút tới trong veo ngọt.', NULL, NULL),
('imp-73568e9a99d0ccdf_step_3', 'imp-73568e9a99d0ccdf', 3, 'Rưới trứng vào chảo, đảo nhanh 2 phút tới bông vàng.', NULL, NULL),
('imp-73568e9a99d0ccdf_step_4', 'imp-73568e9a99d0ccdf', 4, 'Nêm xì dầu nhẹ, rắc hành lá dùng ngay.', NULL, NULL),
('imp-a17f5a86a1bc891c_step_1', 'imp-a17f5a86a1bc891c', 1, 'Ba chỉ luộc nước sôi có gừng lát-hành lá 25 phút tới chín mềm.', NULL, 25),
('imp-a17f5a86a1bc891c_step_2', 'imp-a17f5a86a1bc891c', 2, 'Vớt thịt để nguội hẳn, thái lát mỏng đều ngang thớ.', NULL, NULL),
('imp-a17f5a86a1bc891c_step_3', 'imp-a17f5a86a1bc891c', 3, 'Pha tương chấm xì dầu-gừng sợi-ớt tùy thích.', NULL, NULL),
('imp-a17f5a86a1bc891c_step_4', 'imp-a17f5a86a1bc891c', 4, 'Xếp thịt đĩa, dùng nguội chấm tương gừng.', NULL, NULL),
('imp-fbbe89a1039604fc_step_1', 'imp-fbbe89a1039604fc', 1, 'Nấm cắt lát dày đều, tỏi băm nhỏ.', NULL, NULL),
('imp-fbbe89a1039604fc_step_2', 'imp-fbbe89a1039604fc', 2, 'Xào tỏi với dầu 20 giây, cho nấm xào lửa lớn 3 phút.', NULL, NULL),
('imp-fbbe89a1039604fc_step_3', 'imp-fbbe89a1039604fc', 3, 'Rưới xì dầu-đường nhẹ, đảo 1 phút nấm bóng thấm.', NULL, NULL),
('imp-fbbe89a1039604fc_step_4', 'imp-fbbe89a1039604fc', 4, 'Rắc hành lá, múc ra đĩa dùng ngay.', NULL, NULL),
('imp-3ee45f761eb0b78d_step_1', 'imp-3ee45f761eb0b78d', 1, 'Ức gà luộc 12 phút xé sợi; mì trần 3 phút xả lạnh để ráo.', NULL, 12),
('imp-3ee45f761eb0b78d_step_2', 'imp-3ee45f761eb0b78d', 2, 'Dưa leo bào sợi, trộn nước sốt xì dầu-tỏi băm-giấm-đường-mè.', NULL, NULL),
('imp-3ee45f761eb0b78d_step_3', 'imp-3ee45f761eb0b78d', 3, 'Trộn mì-gà-dưa leo với sốt cho đều.', NULL, NULL),
('imp-3ee45f761eb0b78d_step_4', 'imp-3ee45f761eb0b78d', 4, 'Rắc hành lá, để mát 10 phút rồi dùng.', NULL, NULL),
('imp-cbb5635bfe848a49_step_1', 'imp-cbb5635bfe848a49', 1, 'Gà chặt miếng ướp xì dầu-tiêu 15 phút.', NULL, NULL),
('imp-cbb5635bfe848a49_step_2', 'imp-cbb5635bfe848a49', 2, 'Xào gừng lát-hành tây 1 phút, cho gà xào săn.', NULL, 3),
('imp-cbb5635bfe848a49_step_3', 'imp-cbb5635bfe848a49', 3, 'Đổ nước xâm xấp, om 20 phút tới nước sánh, thịt mềm.', NULL, 20),
('imp-cbb5635bfe848a49_step_4', 'imp-cbb5635bfe848a49', 4, 'Rắc hành lá, dùng nóng với cơm.', NULL, NULL),
('imp-7bf9327b2c48f2d4_step_1', 'imp-7bf9327b2c48f2d4', 1, 'Sườn khứa mặt ướp xì dầu-đường-tỏi băm 30 phút.', NULL, 30),
('imp-7bf9327b2c48f2d4_step_2', 'imp-7bf9327b2c48f2d4', 2, 'Nướng lò 220 độ 18 phút, quét sốt ướp thừa giữa chừng.', NULL, 18),
('imp-7bf9327b2c48f2d4_step_3', 'imp-7bf9327b2c48f2d4', 3, 'Nướng tới mặt sườn cháy cạnh bóng caramel.', NULL, NULL),
('imp-7bf9327b2c48f2d4_step_4', 'imp-7bf9327b2c48f2d4', 4, 'Rắc hành lá, dùng nóng với cơm.', NULL, NULL),
('imp-bbfdcf2e3b277fed_step_1', 'imp-bbfdcf2e3b277fed', 1, 'Luộc gà 12 phút xé sợi, giữ nước luộc nêm xì dầu-mirin? nêm xì dầu-đường thành nước dùng.', NULL, NULL),
('imp-bbfdcf2e3b277fed_step_2', 'imp-bbfdcf2e3b277fed', 2, 'Soba trần 3 phút tới mềm, vớt ráo.', NULL, NULL),
('imp-bbfdcf2e3b277fed_step_3', 'imp-bbfdcf2e3b277fed', 3, 'Xếp soba-gà vào tô, chan nước dùng sôi.', NULL, NULL),
('imp-bbfdcf2e3b277fed_step_4', 'imp-bbfdcf2e3b277fed', 4, 'Rắc hành lá-gừng bào, dùng nóng.', NULL, NULL),
('imp-f2334219f33e48d0_step_1', 'imp-f2334219f33e48d0', 1, 'Tôm cắt râu rạch lưng, rắc muối thô hai mặt.', NULL, NULL),
('imp-f2334219f33e48d0_step_2', 'imp-f2334219f33e48d0', 2, 'Nướng than hoặc lò 220 độ 7 phút tới vỏ đỏ cháy cạnh.', NULL, 7),
('imp-f2334219f33e48d0_step_3', 'imp-f2334219f33e48d0', 3, 'Lật nướng thêm 3 phút cho đều.', NULL, 3),
('imp-f2334219f33e48d0_step_4', 'imp-f2334219f33e48d0', 4, 'Dùng nóng bóc vỏ, vắt chanh chấm muối.', NULL, NULL),
('imp-8f6eeb8b34b7cd65_step_1', 'imp-8f6eeb8b34b7cd65', 1, 'Gạo nấu chín tới, trộn xì dầu-gừng băm thành nhân.', NULL, NULL),
('imp-8f6eeb8b34b7cd65_step_2', 'imp-8f6eeb8b34b7cd65', 2, 'Mực làm sạch, nhồi cơm 2/3 thân, dùng tăm xiên miệng.', NULL, NULL),
('imp-8f6eeb8b34b7cd65_step_3', 'imp-8f6eeb8b34b7cd65', 3, 'Om mực trong xì dầu-đường 10 phút rồi nướng 10 phút quét sốt.', NULL, 20),
('imp-8f6eeb8b34b7cd65_step_4', 'imp-8f6eeb8b34b7cd65', 4, 'Cắt khoanh, rắc hành lá dùng nóng.', NULL, NULL),
('imp-9e4ad3e4074d2a1c_step_1', 'imp-9e4ad3e4074d2a1c', 1, 'Bắp cải thái sợi mỏng ngâm nước đá 5 phút cho giòn, vắt ráo.', NULL, NULL),
('imp-9e4ad3e4074d2a1c_step_2', 'imp-9e4ad3e4074d2a1c', 2, 'Tôm luộc 3 phút bóc vỏ bổ đôi.', NULL, NULL),
('imp-9e4ad3e4074d2a1c_step_3', 'imp-9e4ad3e4074d2a1c', 3, 'Pha sốt giấm-chanh-xì dầu-đường nhẹ nhàng.', NULL, NULL),
('imp-9e4ad3e4074d2a1c_step_4', 'imp-9e4ad3e4074d2a1c', 4, 'Trộn bắp cải-tôm với sốt, rắc hành lá dùng mát.', NULL, NULL),
('imp-4023e971948407f6_step_1', 'imp-4023e971948407f6', 1, 'Cá hồi cắt miếng rắc muối nhẹ, xào hành tây-cà chua mềm ra sốt.', NULL, NULL),
('imp-4023e971948407f6_step_2', 'imp-4023e971948407f6', 2, 'Đặt cá hồi lên, thêm xì dầu-đường và nửa chén nước.', NULL, NULL),
('imp-4023e971948407f6_step_3', 'imp-4023e971948407f6', 3, 'Om lửa nhỏ 12 phút tới cá chín thấm, rưới sốt lên mặt.', NULL, NULL),
('imp-4023e971948407f6_step_4', 'imp-4023e971948407f6', 4, 'Rắc hành lá, dùng nóng chan cơm.', NULL, NULL),
('imp-76ddca35768468fe_step_1', 'imp-76ddca35768468fe', 1, 'Bò thái lát mỏng đều, thấm khô trước khi nướng.', NULL, NULL),
('imp-76ddca35768468fe_step_2', 'imp-76ddca35768468fe', 2, 'Nướng vỉ lửa lớn 1 phút mỗi mặt tới cháy cạnh.', NULL, 2),
('imp-76ddca35768468fe_step_3', 'imp-76ddca35768468fe', 3, 'Pha muối-chanh bào vỏ tỏi làm chấm.', NULL, NULL),
('imp-76ddca35768468fe_step_4', 'imp-76ddca35768468fe', 4, 'Nhúng thịt nóng chấm muối chanh, rắc hành lá dùng ngay.', NULL, NULL),
('imp-1bbb2341036dd966_step_1', 'imp-1bbb2341036dd966', 1, 'Bông cải tách nhánh chần 2 phút, ngâm nước lạnh giữ xanh, để ráo.', NULL, 3),
('imp-1bbb2341036dd966_step_2', 'imp-1bbb2341036dd966', 2, 'Mè rang vàng giã thô trộn xì dầu-đường.', NULL, NULL),
('imp-1bbb2341036dd966_step_3', 'imp-1bbb2341036dd966', 3, 'Trộn bông cải với sốt mè cho áo đều.', NULL, NULL),
('imp-1bbb2341036dd966_step_4', 'imp-1bbb2341036dd966', 4, 'Rắc hành lá, bày rau phụ dùng mát.', NULL, NULL),
('imp-5ed977305ac677b6_step_1', 'imp-5ed977305ac677b6', 1, 'Múc cơm nóng ra tô, đặt viên bơ giữa mặt.', NULL, NULL),
('imp-5ed977305ac677b6_step_2', 'imp-5ed977305ac677b6', 2, 'Rưới xì dầu quanh bơ, đợi 30 giây bơ tan.', NULL, NULL),
('imp-5ed977305ac677b6_step_3', 'imp-5ed977305ac677b6', 3, 'Trộn đều cơm-bơ-xì dầu. Bước này thực hiện chậm rãi, khuấy đều tay để nguyên liệu chín đều và thấm vị.', NULL, NULL),
('imp-5ed977305ac677b6_step_4', 'imp-5ed977305ac677b6', 4, 'Rắc hành lá, dùng ngay khi cơm còn nóng.', NULL, NULL),
('imp-57294c4da3e61e24_step_1', 'imp-57294c4da3e61e24', 1, 'Nấm cắt lát, đun 800ml nước với nấm 4 phút.', NULL, NULL),
('imp-57294c4da3e61e24_step_2', 'imp-57294c4da3e61e24', 2, 'Thả tôm nấu 2 phút tới chín hồng.', NULL, NULL),
('imp-57294c4da3e61e24_step_3', 'imp-57294c4da3e61e24', 3, 'Hòa miso với nước canh nóng đổ lại, không sôi lại.', NULL, NULL),
('imp-57294c4da3e61e24_step_4', 'imp-57294c4da3e61e24', 4, 'Rắc hành lá, dùng nóng trước bữa cơm.', NULL, NULL),
('imp-ea9ba867b7d2c6ad_step_1', 'imp-ea9ba867b7d2c6ad', 1, 'Ức gà rắc muối-gừng bào 10 phút.', NULL, NULL),
('imp-ea9ba867b7d2c6ad_step_2', 'imp-ea9ba867b7d2c6ad', 2, 'Lót bắp cải xé dưới đĩa, đặt gà lên hấp 15 phút.', NULL, NULL),
('imp-ea9ba867b7d2c6ad_step_3', 'imp-ea9ba867b7d2c6ad', 3, 'Gà chín thái lát, rưới xì dầu pha gừng sợi nóng.', NULL, NULL),
('imp-ea9ba867b7d2c6ad_step_4', 'imp-ea9ba867b7d2c6ad', 4, 'Rắc hành lá, dùng nóng cùng bắp cải hấp.', NULL, NULL),
('imp-7d764feba948bce3_step_1', 'imp-7d764feba948bce3', 1, 'Xào kim chi-tỏi 3 phút ra nước đỏ, đổ 800ml nước đun sôi.', NULL, NULL),
('imp-7d764feba948bce3_step_2', 'imp-7d764feba948bce3', 2, 'Nêm xì dầu, thả cá cắt khúc nấu 6 phút.', NULL, 6),
('imp-7d764feba948bce3_step_3', 'imp-7d764feba948bce3', 3, 'Thả đậu phụ miếng nấu 4 phút nhẹ tay.', NULL, NULL),
('imp-7d764feba948bce3_step_4', 'imp-7d764feba948bce3', 4, 'Rắc hành lá, dùng nóng với cơm.', NULL, NULL),
('imp-a24e0f07380bfdc2_step_1', 'imp-a24e0f07380bfdc2', 1, 'Sườn ngâm nước 30 phút cho sạch, chần nước sôi 3 phút.', NULL, 30),
('imp-a24e0f07380bfdc2_step_2', 'imp-a24e0f07380bfdc2', 2, 'Om sườn với xì dầu-tỏi-đường-gừng 60 phút lửa nhỏ.', NULL, 60),
('imp-a24e0f07380bfdc2_step_3', 'imp-a24e0f07380bfdc2', 3, 'Thả cà rốt-hành tây om thêm 15 phút nước sánh.', NULL, NULL),
('imp-a24e0f07380bfdc2_step_4', 'imp-a24e0f07380bfdc2', 4, 'Rắc hành lá-mè, dùng nóng với cơm.', NULL, NULL),
('imp-706c3678abea88b4_step_1', 'imp-706c3678abea88b4', 1, 'Trứng đánh tan với hành lá cắt nhỏ-xì dầu nhẹ.', NULL, NULL),
('imp-706c3678abea88b4_step_2', 'imp-706c3678abea88b4', 2, 'Đổ trứng chảo nóng dầu mỏng lửa vừa.', NULL, NULL),
('imp-706c3678abea88b4_step_3', 'imp-706c3678abea88b4', 3, 'Nấu 2 phút tới viền vàng giòn, lật 1 phút mặt còn lại.', NULL, 3),
('imp-706c3678abea88b4_step_4', 'imp-706c3678abea88b4', 4, 'Trút ra đĩa tròn, cắt múi dùng với cơm.', NULL, NULL),
('imp-d88e008b28a31151_step_1', 'imp-d88e008b28a31151', 1, 'Mực thái khoanh khứa vằn, chần nước sôi 30 giây cong giòn.', NULL, NULL),
('imp-d88e008b28a31151_step_2', 'imp-d88e008b28a31151', 2, 'Xào tỏi-kim chi cắt khúc 3 phút ra nước cay đỏ.', NULL, NULL),
('imp-d88e008b28a31151_step_3', 'imp-d88e008b28a31151', 3, 'Thả mực xào lửa lớn 2 phút, nêm xì dầu-đường.', NULL, NULL),
